css:
        /* ===== [v2.2] TAMPILAN HP & APLIKASI TERPASANG ===== */
        .nav-bawah { display: none; }
        .kartu-pasang { display: none; }
        @media (max-width: 767.98px) {
            body { padding-bottom: calc(66px + env(safe-area-inset-bottom)); }
            .nav-bawah { display: flex; position: fixed; left: 0; right: 0; bottom: 0; z-index: 1040; padding: 0 4px env(safe-area-inset-bottom);
                background: rgba(9, 22, 40, .97); backdrop-filter: blur(12px); border-top: 1px solid rgba(255, 255, 255, .1); box-shadow: 0 -6px 20px rgba(0, 0, 0, .25); }
            .nav-bawah button { flex: 1; min-width: 0; height: 60px; border: 0; background: none; color: #93A9BF; display: flex; flex-direction: column; align-items: center; justify-content: center;
                gap: 4px; font-size: .66rem; font-weight: 600; letter-spacing: .01em; -webkit-tap-highlight-color: transparent; position: relative; }
            .nav-bawah button i { font-size: 1.18rem; }
            .nav-bawah button.aktif { color: #F59A3C; }
            .nav-bawah button.aktif::before { content: ''; position: absolute; top: 0; left: 28%; right: 28%; height: 3px; border-radius: 0 0 3px 3px; background: #F28C28; }
            .nav-bawah .bdg { position: absolute; top: 7px; left: calc(50% + 6px); min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; background: #E5484D; color: #fff; font-size: .6rem; line-height: 16px; }
            .fab-home { display: none !important; }
            #toastWadah { left: 12px !important; right: 12px !important; bottom: calc(76px + env(safe-area-inset-bottom)) !important; max-width: none !important; }
            /* header ringkas satu baris */
            .app-header { flex-wrap: nowrap !important; padding-top: .5rem !important; padding-bottom: .6rem !important; margin-bottom: .75rem !important; }
            .app-header .crumb { display: none !important; }
            .app-header .judul-halaman { font-size: 1.3rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
            .app-header > div:last-child { flex-wrap: nowrap !important; gap: 6px !important; }
            .prj-chip, #chipKoneksi { display: none !important; }
            #chipUser { max-width: 46px; overflow: hidden; padding-left: 4px; padding-right: 4px; }
            #chipUser .nm-user, #chipUser .badge, #chipUser.dropdown-toggle::after { display: none !important; }
            /* dashboard */
            .dash-hero-gambar { display: none !important; }
            .dash-hero { padding: 18px !important; }
            .hero-eyebrow { font-size: .62rem !important; }
            .hero-judul { font-size: 1.3rem !important; }
            .hero-metrik { gap: 12px !important; }
            .hero-mini { grid-template-columns: 1fr 1fr !important; gap: 8px !important; }
            .hero-mini .hm:first-child { grid-column: 1 / -1; }
            .hero-aksi { display: grid !important; grid-template-columns: 1fr 1fr; gap: 8px; }
            .hero-aksi .hero-btn { width: 100%; justify-content: center; }
            /* formulir nyaman disentuh, tanpa zoom otomatis iOS */
            input.form-control, select.form-select, textarea.form-control, .form-control, .form-select { font-size: 16px; min-height: 42px; }
            .btn { min-height: 38px; }
            .table-responsive { -webkit-overflow-scrolling: touch; }
            .modal-dialog { margin: .5rem; }
            .kartu-pasang { display: flex; position: fixed; left: 12px; right: 12px; bottom: calc(74px + env(safe-area-inset-bottom)); z-index: 1041; align-items: center; gap: 12px;
                padding: 12px 14px; border-radius: 14px; background: linear-gradient(135deg, #12325E, #1F6FD1); color: #fff; box-shadow: 0 14px 34px rgba(0, 0, 0, .35); }
            .kartu-pasang img { width: 42px; height: 42px; border-radius: 10px; background: #fff; flex: none; }
            .kartu-pasang[hidden] { display: none; }
        }
        @media (display-mode: standalone) {
            .app-header { padding-top: calc(.5rem + env(safe-area-inset-top)) !important; }
            .layar-masuk { padding-top: env(safe-area-inset-top); }
            .sidebar.show { padding-top: env(safe-area-inset-top); }
        }
        @media (max-width: 767.98px) { .sidebar .sb-kbd:not(#sbVersi) { display: none; } }
        @media (max-width: 767.98px) {
            html:not([data-tema="gelap"]) .nav-bawah { background: rgba(255, 255, 255, .97); border-top-color: #DCE3EE; box-shadow: 0 -6px 20px rgba(11, 31, 58, .08); }
            html:not([data-tema="gelap"]) .nav-bawah button { color: #6B7C93; }
            html:not([data-tema="gelap"]) .nav-bawah button.aktif { color: #D9730D; }
        }
        .banner-server-lama code { background: rgba(0, 0, 0, .08); padding: 1px 5px; border-radius: 4px; }

        /* 2.0.4 — WBS di Monitoring BK */
        .wbs-bdg { display: inline-flex; align-items: center; padding: 2px 7px; border-radius: 999px; font-size: .74rem; font-weight: 700; text-decoration: none; white-space: nowrap; }
        .wbs-bdg.kurang { background: rgba(229, 83, 75, .14); color: #D23B34; border: 1px solid rgba(229, 83, 75, .45); }
        .wbs-bdg.kurang:hover { background: #E5534B; color: #fff; }
        html[data-tema="gelap"] .wbs-bdg.kurang { color: #FF8A84; }
        #bkWbsInfo .btn-light { font-size: .78rem; }

/* ===== 2.1.0 MONITORING PENGADAAN — tema Waskita (navy #0B2B54 · biru #1763B3 · merah #E3343F) ===== */
:root {
    --w-navy: #0B2B54; --w-navy2: #103A6E; --w-biru: #1763B3; --w-biru2: #2D7FD3; --w-langit: #4C9BEA; --w-merah: #E3343F; --w-merah2: #FF5A64;
    --pro-navy: #0B2B54; --pro-navy2: #103A6E; --pro-navy3: #1763B3; --pro-biru: #1763B3; --pro-biru2: #2D7FD3; --pro-langit: #4C9BEA;
    --pro-oranye: #E3343F; --pro-oranye2: #FF6B74; --pro-merah: #E3343F;
    --pel-accent: #4C9BEA; --pel-accent-ink: #04121F; --pel-red: #E3343F; --pel-steel: #1763B3;
}
/* tema gelap → navy Waskita */
html[data-tema="gelap"] body {
    --pel-bg: #071630; --pel-panel: rgba(12, 32, 62, .84); --pel-panel-solid: #0C2242; --pel-line: #1B3A66; --pel-line2: #27508A;
    --bs-link-color: #7DB8F2; --bs-link-color-rgb: 125, 184, 242; --bs-link-hover-color-rgb: 76, 155, 234;
    background: radial-gradient(1100px 620px at 8% -8%, rgba(23, 99, 179, .28), transparent 60%) fixed,
        radial-gradient(800px 500px at 100% 105%, rgba(227, 52, 63, .10), transparent 60%) fixed,
        linear-gradient(160deg, #061229 0%, #0A1D3D 50%, #071631 100%) fixed !important;
}
html[data-tema="gelap"] .sidebar { background: rgba(5, 16, 36, .86); }
html[data-tema="gelap"] .sidebar .nav-link.active { color: #fff; background: linear-gradient(90deg, rgba(23, 99, 179, .38), rgba(23, 99, 179, .05)); border-left-color: var(--w-merah); }
html[data-tema="gelap"] .sidebar .nav-link.active i { color: var(--w-merah2); }
html[data-tema="gelap"] .btn-primary { --bs-btn-bg: #1E6FC4; --bs-btn-border-color: #1E6FC4; --bs-btn-color: #fff; --bs-btn-hover-bg: #2D7FD3; --bs-btn-hover-border-color: #2D7FD3; --bs-btn-hover-color: #fff;
    --bs-btn-active-bg: #1763B3; --bs-btn-active-color: #fff; --bs-btn-disabled-bg: #24456F; --bs-btn-disabled-border-color: #24456F; --bs-btn-disabled-color: #9FB6D3; }
html[data-tema="gelap"] .btn-outline-primary { --bs-btn-color: #7DB8F2; --bs-btn-border-color: rgba(76, 155, 234, .55); --bs-btn-hover-bg: #1E6FC4; --bs-btn-hover-border-color: #1E6FC4; --bs-btn-hover-color: #fff; --bs-btn-active-bg: #1763B3; --bs-btn-active-color: #fff; }
html[data-tema="gelap"] .btn-link, html[data-tema="gelap"] code, html[data-tema="gelap"] .badge.bg-light { --bs-btn-color: #7DB8F2; color: #7DB8F2 !important; }
html[data-tema="gelap"] .form-control:focus, html[data-tema="gelap"] .form-select:focus { border-color: var(--w-langit); box-shadow: 0 0 0 .2rem rgba(76, 155, 234, .22); }
html[data-tema="gelap"] .reg-chip.aktif { background: #1E6FC4; border-color: #1E6FC4; color: #fff; }
html[data-tema="gelap"] .kpi .kpi-icon, html[data-tema="gelap"] .cmdk-item .ik { background: rgba(76, 155, 234, .14); color: #7DB8F2; }
html[data-tema="gelap"] .cmdk-item.aktif, html[data-tema="gelap"] .ac-list .list-group-item.active-ac { background: rgba(76, 155, 234, .14); }
html[data-tema="gelap"] .table { --bs-table-hover-bg: rgba(76, 155, 234, .07); }
html[data-tema="gelap"] .modal-header[style], html[data-tema="gelap"] .offcanvas-header[style] { border-bottom-color: var(--w-merah) !important; }
html[data-tema="gelap"] .progress-bar:not(.bg-success) { background-color: var(--w-langit); }
html[data-tema="gelap"] .crumb #crumbNow, html[data-tema="gelap"] .crumb .btn-home:hover { color: #7DB8F2; }
html[data-tema="gelap"] .bk-tahap .l, html[data-tema="gelap"] .pill-cek.sebagian { color: #7DB8F2; }
/* tema terang */
html:not([data-tema="gelap"]) .sidebar { background: linear-gradient(180deg, #0B2B54 0%, #0E3466 55%, #0B2B54 100%); }
html:not([data-tema="gelap"]) .sidebar .nav-link.active { background: linear-gradient(90deg, rgba(76, 155, 234, .28), rgba(76, 155, 234, .05)); box-shadow: inset 3px 0 0 var(--w-merah); }
html:not([data-tema="gelap"]) .btn-primary { --bs-btn-bg: #1763B3; --bs-btn-border-color: #1763B3; --bs-btn-hover-bg: #0F4F94; --bs-btn-hover-border-color: #0F4F94; --bs-btn-active-bg: #0B2B54; }
.crumb #crumbNow { color: var(--w-biru); }
.crumb .btn-home:hover { border-color: var(--w-biru); color: var(--w-biru); }
/* elemen bersama */
.prj-chip { border-color: rgba(23, 99, 179, .5); background: rgba(23, 99, 179, .10); }
.prj-chip .id { background: var(--w-merah); color: #fff; }
.sb-proyek .id, html:not([data-tema="gelap"]) .sb-proyek .id { color: var(--w-merah2); }
.brand-logo, .masuk-logo { box-shadow: 0 6px 16px rgba(227, 52, 63, .25); }
.brand-logo img, .masuk-logo img { width: 100%; height: 100%; border-radius: inherit; display: block; }
.masuk-eyebrow, .hero-eyebrow { color: var(--w-merah2) !important; }
.masuk-kartu { border-color: rgba(76, 155, 234, .35); }
.masuk-fitur i { background: rgba(227, 52, 63, .14); color: var(--w-merah2); }
.btn-masuk { background: linear-gradient(135deg, #0B2B54, #1763B3); }
.btn-masuk:hover { background: linear-gradient(135deg, #0E3466, #2D7FD3); color: #fff; }
html[data-tema] .masuk-kanan .form-control:focus, html[data-tema] .masuk-kanan .form-select:focus { border-color: var(--w-biru); box-shadow: 0 0 0 .2rem rgba(23, 99, 179, .2); }
.layar-masuk { background: radial-gradient(900px 520px at 12% 8%, rgba(23, 99, 179, .35), transparent 60%), radial-gradient(800px 520px at 92% 92%, rgba(227, 52, 63, .14), transparent 60%), linear-gradient(150deg, #051026, #0B2B54 55%, #061533) !important; }
.dash-hero { border-color: rgba(76, 155, 234, .3) !important; }
.hero-ring .ring-isi { stroke: var(--w-merah); }
.hero-btn.utama { background: var(--w-merah); border-color: var(--w-merah); color: #fff; }
.hero-btn.utama:hover { background: var(--w-merah2); color: #fff; }
.fab-home { background: var(--w-merah); color: #fff; }
.fab-home:hover { background: var(--w-merah2); }
.alur-step:hover, .folder.buka, .status-tile:hover { border-color: var(--w-biru) !important; }
.alur-step:not(:last-child)::after { background: var(--w-merah) !important; color: #fff !important; }
.mini-bar span { background: var(--w-biru); }
.nav-bawah button.aktif::before { background: var(--w-merah) !important; }
.banner-pembaruan > i { color: var(--w-merah2); }
.alur-pengadaan { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)) !important; }
@media (max-width: 767.98px) { .alur-pengadaan { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; } .alur-step::after { display: none !important; } }

/* ===== Paket PBJ ===== */
.pbj-bingkai { border: 1px solid rgba(127, 127, 127, .25); border-radius: 12px; overflow: hidden; background: #081A33; }
.pbj-bingkai iframe { width: 100%; height: calc(100vh - 250px); min-height: 620px; border: 0; display: block; }
@media (max-width: 767.98px) { .pbj-bingkai iframe { height: calc(100vh - 170px); min-height: 520px; } }
.pbj-bar { border-top: 3px solid var(--w-merah) !important; }
.alur-mini { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 8px; }
.alur-mini .am { flex: 1 1 100px; min-width: 0; border-radius: 8px; padding: 4px 8px; border: 1px solid rgba(127, 127, 127, .25); background: rgba(127, 127, 127, .05); position: relative; }
.alur-mini .am .t { display: block; font-family: var(--font-judul); font-size: .68rem; letter-spacing: .1em; text-transform: uppercase; opacity: .7; }
.alur-mini .am .v { display: block; font-size: .78rem; font-family: var(--font-angka); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.alur-mini .am.ok { border-color: rgba(46, 158, 91, .55); background: rgba(46, 158, 91, .09); }
.alur-mini .am.jalan { border-color: rgba(23, 99, 179, .55); background: rgba(23, 99, 179, .09); }
.tbl-pbj td, .tbl-alur td { vertical-align: middle; }
/* ===== Lacak alur ===== */
.alr-funnel { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); gap: 6px; }
@media (max-width: 991.98px) { .alr-funnel { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.alr-f { text-align: left; border: 1px solid rgba(127, 127, 127, .25); border-radius: 10px; padding: 8px 10px; background: rgba(127, 127, 127, .04); color: inherit; position: relative; overflow: hidden; }
.alr-f::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--w-biru); }
.alr-f:nth-child(n+5)::before { background: var(--w-merah); }
.alr-f.aktif { border-color: var(--w-biru); box-shadow: 0 0 0 2px rgba(23, 99, 179, .25); }
.alr-f .no { font-family: var(--font-angka); font-size: .68rem; opacity: .6; }
.alr-f .l { font-family: var(--font-judul); font-weight: 600; font-size: .82rem; letter-spacing: .04em; text-transform: uppercase; }
.alr-f .v { font-family: var(--font-angka); font-size: 1.3rem; font-weight: 600; }
.alr-f .s { font-size: .68rem; opacity: .7; }
.alr-dot { display: inline-block; width: 12px; height: 12px; border-radius: 50%; border: 2px solid rgba(127, 127, 127, .45); }
.alr-dot.ok { background: #2E9E5B; border-color: #2E9E5B; }
.alr-dot.now { border-color: var(--w-merah); background: rgba(227, 52, 63, .2); box-shadow: 0 0 0 3px rgba(227, 52, 63, .15); }
#tab-pbj .bk-kpi, #tab-keuangan .bk-kpi { overflow: hidden; min-width: 0; }
#tab-pbj .bk-kpi .v, #tab-pbj .bk-kpi .s, #tab-keuangan .bk-kpi .v, #tab-keuangan .bk-kpi .s { white-space: normal; overflow-wrap: anywhere; }
/* dari kandidat 2.0.7 (visual): WBS, modal WBS/gambar BK, kartu pasang */
.kartu-pasang { background: linear-gradient(135deg, #0B2B54, #1763B3); }
.wbs-bdg.kurang { background: rgba(227, 52, 63, .13); color: #D82A37; border-color: rgba(227, 52, 63, .46); }
#modalWbs .modal-header, #modalGambarBK .modal-header { background: linear-gradient(100deg, #0B2B54, #1459A4) !important; border-bottom: 3px solid #E3343F; }

/* ===== 2.1.4 — Monitoring Pengadaan: menu ringkas, dashboard ringkas, rekap kontrak, master data, alokasi, klarifikasi ===== */
/* --- Menu kiri ringkas: seluruh menu terlihat tanpa gulir pada laptop (≥ 600 px tinggi) --- */
@media (min-width: 768px) {
    .sidebar.mp214-sb { padding: 10px 10px 8px !important; font-size: .82rem; overflow-y: auto; scrollbar-width: thin; }
    .mp214-sb > .py-2 { padding-top: 2px !important; padding-bottom: 2px !important; }
    .mp214-sb .brand-logo { width: 34px !important; height: 34px !important; border-radius: 9px; padding: 2px; }
    .mp214-sb .brand-nama { font-size: 1.08rem !important; line-height: 1.05; }
    .mp214-sb .brand-tag { font-size: .55rem !important; letter-spacing: .1em; }
    .mp214-sb .sb-proyek { margin-top: 7px !important; padding: 5px 8px !important; border-radius: 9px; font-size: .72rem; line-height: 1.2; }
    .mp214-sb .sb-proyek .small { display: none; }
    .mp214-sb .sb-proyek > div:nth-child(2) { display: inline; }
    .mp214-sb .sb-proyek .fw-semibold { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .mp214-sb hr { margin: 7px 0 !important; }
    .mp214-sb .nav { gap: 1px; flex-wrap: nowrap; }
    .mp214-sb .nav-item { margin-bottom: 0 !important; }
    .mp214-sb .nav-link { padding: .3rem .6rem !important; font-size: .82rem; line-height: 1.25; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .mp214-sb .nav-link i { width: 16px; font-size: .82rem; margin-right: .5rem !important; text-align: center; }
    html[data-tema="gelap"] .mp214-sb .nav-link { padding-left: calc(.6rem + 7px) !important; margin-left: -10px; }
    .mp214-sb .sb-user { padding-top: 8px !important; }
    .mp214-sb .sb-user .kartu { padding: 6px 8px; gap: 8px; border-radius: 10px; }
    .mp214-sb .sb-user .ava-md, .mp214-sb .sb-user .avatar { width: 30px !important; height: 30px !important; font-size: .72rem !important; }
    .mp214-sb .sb-user .nm { font-size: .8rem; }
    .mp214-sb .sb-user .pr { font-size: .66rem; }
    .mp214-sb .sb-kbd { margin-top: 5px !important; font-size: .62rem !important; }
    .mp214-sb .sb-user .sb-kbd { display: none; }
}
@media (min-width: 768px) and (max-height: 700px) {
    .mp214-sb .brand-tag { display: none; }
    .mp214-sb .nav-link { padding-top: .24rem !important; padding-bottom: .24rem !important; }
    .mp214-sb hr { margin: 5px 0 !important; }
}
/* --- Dashboard ringkas: hero, langkah, KPI, grafik lebih pendek → ruang untuk Rekap Kontrak --- */
.mp214-dash .dash-hero { padding: 14px 20px !important; grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr) !important; margin-bottom: 12px !important; }
.mp214-dash .hero-judul { font-size: 1.45rem !important; margin: 2px 0 2px !important; }
.mp214-dash .hero-eyebrow { font-size: .68rem; }
.mp214-dash .hero-sub { font-size: .8rem; }
.mp214-dash .hero-metrik { margin: 8px 0 8px !important; gap: 12px !important; }
.mp214-dash .hero-ring { width: 78px !important; height: 78px !important; }
.mp214-dash .hero-ring .ring-teks b { font-size: 1rem !important; }
.mp214-dash .hero-ring .ring-teks span { font-size: .5rem !important; }
.mp214-dash .hero-mini .hm { padding: 6px 9px !important; }
.mp214-dash .hero-mini .hm-v { font-size: .95rem !important; }
.mp214-dash .hero-mini .hm-l { font-size: .66rem !important; }
.mp214-dash .hero-btn { padding: 3px 11px !important; font-size: .78rem; }
.mp214-dash .dash-hero-gambar svg { max-height: 150px !important; }
.mp214-dash .alur-pengadaan { gap: 8px !important; margin-bottom: 12px !important; grid-template-columns: repeat(7, minmax(0, 1fr)) !important; }
.mp214-dash .alur-step { padding: 8px 10px !important; border-radius: 10px !important; }
.mp214-dash .alur-step .ik { width: 26px !important; height: 26px !important; font-size: .78rem !important; border-radius: 7px !important; }
.mp214-dash .alur-step .no { font-size: .58rem !important; }
.mp214-dash .alur-step .l { font-size: .76rem !important; line-height: 1.1; }
.mp214-dash .alur-step .v { font-size: 1.15rem !important; }
.mp214-dash .alur-step .s { font-size: .64rem !important; line-height: 1.2; }
.mp214-dash .alur-step:not(:last-child)::after { width: 16px !important; height: 16px !important; right: -9px !important; font-size: .55rem !important; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
.mp214-dash .kpi { padding: 10px 14px !important; }
.mp214-dash .kpi .kpi-label { font-size: .68rem !important; }
.mp214-dash .kpi .kpi-value { font-size: 1.2rem !important; margin: 2px 0 0 !important; }
.mp214-dash .kpi .kpi-sub { font-size: .72rem !important; }
.mp214-dash .kpi .kpi-icon { width: 28px !important; height: 28px !important; font-size: .8rem !important; }
.mp214-dash > .row.g-3.mb-3 { --bs-gutter-y: .6rem; --bs-gutter-x: .6rem; margin-bottom: .75rem !important; }
.mp214-dash .mp214-status { padding: 10px 12px !important; margin-bottom: .75rem !important; }
.mp214-dash .status-tile { padding: 7px 10px !important; }
.mp214-dash .status-tile .st-count { font-size: 1.1rem !important; }
.mp214-dash .status-tile .st-label { font-size: .76rem !important; }
.mp214-dash .chart-card { padding: 10px 12px !important; }
.mp214-dash .chart-card h6 { font-size: .82rem; }
.mp214-dash .chart-box, .mp214-dash .chart-box.tinggi { height: 200px !important; }
