/* ===== [v2.1.9] Keuangan & Bayar · Checklist · Rilis Admin-first — palet Waskita (navy · biru · merah) ===== */
:root { --w-navy: #0B2B54; --w-biru: #1763B3; --w-biru2: #1F78D1; --w-merah: #E3343F; --w-hijau: #2E9E5B;
  --f-bg: #fff; --f-ink: #14233A; --f-muted: #61708A; --f-line: #E1E7F0; --f-head: #F3F6FB; --f-soft: #F7F9FC; --f-hover: #F2F7FE; --f-shadow: 0 1px 2px rgba(16,24,40,.05), 0 8px 24px rgba(16,24,40,.06); }
html[data-tema="gelap"] { --f-bg: #0F1E30; --f-ink: #E6EDF6; --f-muted: #98A9BF; --f-line: rgba(255,255,255,.10); --f-head: rgba(255,255,255,.04); --f-soft: rgba(255,255,255,.03); --f-hover: rgba(53,140,230,.10); --f-shadow: 0 1px 2px rgba(0,0,0,.3); }
#tab-keuangan.mp219-keu-tab > h3 { display: none; }
.mp219-keu { display: flex; flex-direction: column; gap: 14px; color: var(--f-ink); }
.mp219-kh { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
.mp219-kh-t { display: flex; align-items: center; gap: 14px; }
.mp219-kh-t h2 { margin: 0; font-size: 1.6rem; font-weight: 800; letter-spacing: -.01em; color: var(--f-ink); }
.mp219-kh-t p { margin: 2px 0 0; color: var(--f-muted); font-size: .92rem; }
.mp219-ik { width: 52px; height: 52px; border-radius: 14px; display: grid; place-items: center; background: linear-gradient(135deg, var(--w-navy), var(--w-biru)); color: #fff; font-size: 1.35rem; box-shadow: 0 8px 18px rgba(11,43,84,.25); flex: none; }
.mp219-kh-a { display: flex; gap: 10px; flex-wrap: wrap; }
.mp219-btn-p { background: var(--w-biru); border: 1px solid var(--w-biru); color: #fff !important; font-weight: 600; border-radius: 10px; display: inline-flex; align-items: center; gap: 8px; }
.mp219-btn-p:hover, .mp219-btn-p:focus-visible { background: #12539A; border-color: #12539A; }
.mp219-btn-o { background: var(--f-bg); border: 1px solid var(--f-line); color: var(--f-ink) !important; font-weight: 600; border-radius: 10px; display: inline-flex; align-items: center; gap: 8px; }
.mp219-btn-o:hover { border-color: var(--w-biru); color: var(--w-biru) !important; }
.mp219-btn-o .fa-file-excel { color: #1D7A45; }
.mp219-kh-a .btn { padding: .55rem 1rem; }
.mp219-tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--f-line); overflow-x: auto; scrollbar-width: none; }
.mp219-tabs button { border: 0; background: none; padding: 10px 16px; color: var(--f-muted); font-weight: 600; border-bottom: 3px solid transparent; margin-bottom: -1px; white-space: nowrap; }
.mp219-tabs button.on { color: var(--w-biru); border-bottom-color: var(--w-biru); }
html[data-tema="gelap"] .mp219-tabs button.on { color: #6FB3FF; border-bottom-color: #6FB3FF; }
.mp219-tabs button:hover { color: var(--f-ink); }
.mp219-kpi { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.mp219-k { background: var(--f-bg); border: 1px solid var(--f-line); border-radius: 14px; padding: 14px 16px; box-shadow: var(--f-shadow); border-top: 4px solid var(--w); }
.mp219-k-l { display: flex; justify-content: space-between; color: var(--f-muted); font-size: .74rem; text-transform: uppercase; letter-spacing: .06em; font-weight: 700; }
.mp219-k-l i { color: var(--w); }
.mp219-k-v { font-size: 1.35rem; font-weight: 800; margin-top: 6px; font-variant-numeric: tabular-nums; }
.mp219-k-s { color: var(--f-muted); font-size: .8rem; }
.mp219-card { background: var(--f-bg); border: 1px solid var(--f-line); border-radius: 14px; box-shadow: var(--f-shadow); overflow: hidden; }
.mp219-fl { display: flex; flex-wrap: wrap; gap: 10px; justify-content: space-between; align-items: center; padding: 12px 14px; border-bottom: 1px solid var(--f-line); }
.mp219-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.mp219-chip { border: 1px solid var(--f-line); background: var(--f-soft); color: var(--f-ink); border-radius: 999px; padding: 4px 10px; font-size: .8rem; font-weight: 600; display: inline-flex; gap: 6px; align-items: center; }
.mp219-chip span { background: rgba(127,127,127,.15); border-radius: 999px; padding: 0 7px; font-size: .72rem; }
.mp219-chip.on { background: var(--w-biru); border-color: var(--w-biru); color: #fff; }
.mp219-chip.on span { background: rgba(255,255,255,.25); }
.mp219-fl2 { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.mp219-fl2 .form-select { width: auto; min-width: 150px; }
.mp219-fl2 input[type=search] { width: 240px; }
.mp219-muat { color: var(--f-muted); font-size: .8rem; }
.mp219-tw { overflow-x: auto; }
.mp219-tb { width: 100%; border-collapse: separate; border-spacing: 0; font-size: .875rem; color: var(--f-ink); }
.mp219-tb thead th { background: var(--f-head); color: var(--f-muted); font-weight: 700; font-size: .78rem; padding: 11px 10px; border-bottom: 1px solid var(--f-line); white-space: nowrap; position: sticky; top: 0; z-index: 1; }
.mp219-tb td { padding: 10px 10px; border-bottom: 1px solid var(--f-line); vertical-align: middle; }
.mp219-tb tbody tr:hover td { background: var(--f-hover); }
.mp219-tb tbody tr:last-child td { border-bottom: 0; }
.mp219-tb .r { text-align: right; } .mp219-tb .c { text-align: center; } .nw { white-space: nowrap; }
.mp219-tb .c-no { width: 44px; color: var(--f-muted); }
.mp219-tb .mono, .mp219-cl .mono { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: .82rem; }
.mp219-tb .b { font-weight: 700; } .mp219 .sub, .mp219-tb .sub, .mp219-cl .sub { color: var(--f-muted); font-size: .76rem; }
.mp219-keu .mp219-tb td:nth-child(2) { max-width: 190px; } .mp219-keu .mp219-tb td:nth-child(5) { min-width: 140px; }
.mp219-pg { display: flex; flex-direction: column; gap: 5px; min-width: 104px; }
.mp219-pg b { font-variant-numeric: tabular-nums; font-size: .9rem; }
.mp219-pg .bar { height: 6px; border-radius: 6px; background: rgba(127,127,127,.18); overflow: hidden; }
.mp219-pg .bar span { display: block; height: 100%; border-radius: 6px; transition: width .3s; }
.mp219-st { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: .76rem; font-weight: 700; white-space: nowrap; color: var(--p); background: color-mix(in srgb, var(--p) 13%, transparent); border: 1px solid color-mix(in srgb, var(--p) 30%, transparent); }
html[data-tema="gelap"] .mp219-st { color: color-mix(in srgb, var(--p) 55%, #fff); }
.mp219-aksi { display: inline-flex; gap: 6px; }
.mp219-aksi button { border: 1px solid var(--f-line); background: var(--f-bg); color: var(--f-ink); border-radius: 8px; padding: 4px 8px; font-size: .76rem; font-weight: 600; display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.mp219-aksi button i { color: var(--w-biru); }
.mp219-aksi button:hover { border-color: var(--w-biru); background: var(--f-hover); }
.mp219-aksi button.u { border-color: color-mix(in srgb, var(--w-merah) 45%, transparent); }
.mp219-aksi button.u i { color: var(--w-merah); }
.mp219-kosong { text-align: center; color: var(--f-muted); padding: 34px !important; }
.mp219-ket { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; padding: 10px 14px; font-size: .78rem; color: var(--f-muted); border-top: 1px solid var(--f-line); background: var(--f-soft); }
.mp219-h { font-weight: 800; color: var(--f-ink); margin-bottom: 10px; }
.mp219-tb-s td, .mp219-tb-s th { padding: 8px 10px; }
@media (max-width: 1199.98px) { .mp219-kpi { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 991.98px) {
  .mp219-fl2 input[type=search] { width: 100%; } .mp219-fl2 { width: 100%; }
  .mp219-keu .mp219-tb:not(.mp219-tb-s):not(.mp219-tc) thead { display: none; }
  .mp219-keu .mp219-tb:not(.mp219-tb-s):not(.mp219-tc) tbody tr { display: grid; grid-template-columns: 1fr 1fr; gap: 2px 12px; padding: 12px 14px; border-bottom: 1px solid var(--f-line); }
  .mp219-keu .mp219-tb:not(.mp219-tb-s):not(.mp219-tc) td { border: 0; padding: 3px 0; text-align: left !important; }
  .mp219-keu .mp219-tb:not(.mp219-tb-s):not(.mp219-tc) td::before { content: attr(data-l); display: block; font-size: .68rem; text-transform: uppercase; letter-spacing: .05em; color: var(--f-muted); font-weight: 700; }
  .mp219-keu .mp219-tb td.c-no, .mp219-keu .mp219-tb td.mp219-kosong { grid-column: 1 / -1; }
