        function pesanServerLama(e) {   // [v2.2] hanya "Aksi tidak dikenal" dari server yang berarti server versi lama
            const m = (e && e.message) || String(e);
            return /aksi tidak dikenal/i.test(m) ? 'Server Apps Script yang aktif masih versi lama, jadi fitur ini belum dikenali. Admin: tempel Code.gs terbaru › Terapkan › Kelola deployment › ikon pensil › Versi: Versi baru › Terapkan.' : m;
        }

        function fileKeFoto(file, ukuran) {
            ukuran = ukuran || 240;
            return new Promise((ok, gagal) => {
                if (!file) return gagal(new Error('Tidak ada foto yang dipilih.'));
                const nama = String(file.name || '').toLowerCase(), heic = /heic|heif/.test(file.type) || /\.(heic|heif)$/.test(nama);
                if (!/^image\//.test(file.type) && !/\.(jpe?g|png|webp|gif|bmp|heic|heif)$/.test(nama)) return gagal(new Error('Pilih berkas gambar (JPG / PNG).'));
                if (file.size > 25 * 1048576) return gagal(new Error('Ukuran foto maksimal 25 MB.'));
                const gambar = src => {
                    const s = Math.min(src.width, src.height), c = document.createElement('canvas');
                    c.width = c.height = ukuran;
                    const x = c.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, ukuran, ukuran);
                    x.imageSmoothingQuality = 'high';
                    x.drawImage(src, (src.width - s) / 2, (src.height - s) / 2, s, s, 0, 0, ukuran, ukuran);
                    let q = .86, out = c.toDataURL('image/jpeg', q);
                    while (out.length > 42000 && q > .4) { q -= .08; out = c.toDataURL('image/jpeg', q); }
                    ok(out);
                };
                const gagalBaca = () => gagal(new Error(heic ? 'Foto format HEIC (iPhone) tidak bisa dibaca browser ini. Kirim/simpan foto sebagai JPG lalu pilih lagi, atau pilih foto dari HP lewat Safari.' : 'Format foto tidak bisa dibaca. Gunakan foto JPG atau PNG.'));
                if (window.createImageBitmap) {
                    createImageBitmap(file, { imageOrientation: 'from-image' }).then(gambar).catch(() => lewatImg());
                } else lewatImg();
                function lewatImg() {
                    const url = URL.createObjectURL(file), im = new Image();
                    im.onload = () => { URL.revokeObjectURL(url); gambar(im); };
                    im.onerror = () => { URL.revokeObjectURL(url); gagalBaca(); };
                    im.src = url;
                }
            });
        }

