            setTeks('prfError', '');
            const btnP = document.querySelector('#modalProfil [onclick="simpanProfil()"]'), isiBtn = btnP ? btnP.innerHTML : '';
            if (btnP) { btnP.disabled = true; btnP.innerHTML = '<i class="fas fa-spinner fa-spin me-1"></i>Menyimpan...'; }
            try {
                const r = await regAksi('ubahProfil', { data });
                const ku = 'JICT_AWAL|' + (REG.url || 'lokal'), ca = bacaSimpan(ku);   // perbarui daftar masuk tersimpan
                if (ca.users) { const x = ca.users.find(v => v.nama === REG.sesi.nama); if (x) { if ('foto' in data) x.foto = (r.user && r.user.foto) || data.foto; x.jabatan = data.jabatan; tulisSimpan(ku, ca); } }
