        const SIMPAN_DATA = {
            _db: null,
            buka() {
                if (!this._db) this._db = new Promise((ok, gagal) => {
                    try { const r = indexedDB.open('JICT_SALINAN', 1); r.onupgradeneeded = () => r.result.createObjectStore('snap'); r.onsuccess = () => ok(r.result); r.onerror = () => gagal(r.error); }
                    catch (e) { gagal(e); }
                });
                return this._db;
            },
            async get(k) { try { const db = await this.buka(); return await new Promise(ok => { const q = db.transaction('snap').objectStore('snap').get(k); q.onsuccess = () => ok(q.result || null); q.onerror = () => ok(null); }); } catch (e) { return null; } },
            async set(k, v) { try { const db = await this.buka(); await new Promise(ok => { const tx = db.transaction('snap', 'readwrite'); tx.objectStore('snap').put(v, k); tx.oncomplete = ok; tx.onerror = ok; tx.onabort = ok; }); } catch (e) { } }
        };

        function kunciSnap(proyek) { return (REG.url || 'lokal') + '|' + (proyek || PROYEK.id); }

        function terapkanData(p, dariSalinan) {
            if (!p || !p.ok) return false;
            if ('migrasi' in p) REG.migrasi = p.migrasi || null;
            if (p.versiServer) REG.versiServer = p.versiServer;
            if (p.tidakBerubah) return false;
            const d = p.data || {};
            REG.data = d.list || []; PROG.data = d.progres || []; PMT.data = d.permintaan || [];
            KOREKSI.data = {}; (d.koreksi || []).forEach(x => { KOREKSI.data[x.key] = x; });
            REG.versiData = p.versi || ''; REG.dataSiap = true;
            if (!dariSalinan && REG.url) SIMPAN_DATA.set(kunciSnap(), { versi: p.versi, data: d, migrasi: REG.migrasi, waktu: Date.now() });
            return true;
        }

