        async function muatDariSalinan() {
            if (!REG.url || !REG.sesi || REG.dataSiap) return;
            const c = await SIMPAN_DATA.get(kunciSnap());
            if (!c || REG.dataSiap || !REG.sesi) return;
            terapkanData({ ok: true, versi: c.versi, data: c.data, migrasi: c.migrasi }, true);
            REG.terakhir = c.waktu ? new Date(c.waktu) : null;
            renderSemuaData();
        }

        async function muatRegister(manual) {
            if (REG.memuat) return;
            if (REG.url && !REG.sesi) { REG.data = []; PROG.data = []; PMT.data = []; KOREKSI.data = {}; REG.dataSiap = false; REG.versiData = ''; renderAllTables(); renderKoneksiReg(); return; }
            REG.memuat = true; renderKoneksiReg();
            let berubah = true;
            try {
                let beres = false;
                if (REG.url && REG.dukungSemua !== false) {   // v2.2: semua data dalam satu panggilan (+ cek versi)
                    const res = await regPost({ action: 'bacaSemua', nama: REG.sesi.nama, pin: REG.sesi.pin, proyek: PROYEK.id, versi: (manual || !REG.dataSiap) ? '' : (REG.versiData || '') });
                    if (!res.ok && /aksi tidak dikenal/i.test(res.error || '')) { REG.dukungSemua = false; REG.versiServer = 'lama'; }
                    else { if (!res.ok) throw new Error(res.error); berubah = terapkanData(res); beres = true; }
                }
                if (!beres) {   // server lama / mode lokal: cara lama (4 panggilan)
                    const res = await regGet('list');
                    if (!res.ok) throw new Error(res.error);
                    const rp = await regGet('progres'); if (!rp || !rp.ok) throw new Error((rp && rp.error) || 'Gagal memuat progres');
                    const rq = await regGet('permintaan'); if (!rq || !rq.ok) throw new Error((rq && rq.error) || 'Gagal memuat permintaan');
                    const rk = await regGet('koreksi');
                    REG.data = res.data || []; PROG.data = rp.data || []; PMT.data = rq.data || [];
                    KOREKSI.data = {}; if (rk && rk.ok) (rk.data || []).forEach(x => { KOREKSI.data[x.key] = x; });
                    if (!REG.url) { REG.migrasi = LOKAL.db().migrasi || null; REG.versiServer = 'lokal'; }
                    REG.dataSiap = true;
                }
                REG.terakhir = new Date(); REG.error = '';
                if (manual) notif('Register tersinkron · ' + REG.data.length + ' kontrak', 'ok');
            } catch (e) {
                REG.error = 'Gagal memuat: ' + e.message;
                if (manual) notif(REG.error, 'err');
            } finally {
                REG.memuat = false;
                if (berubah || REG.error) renderSemuaData(); else { renderKoneksiReg(); renderBannerMigrasi(); }
            }
        }

