        async function muatPenggunaLogin() {
            const sel = document.getElementById('loginNama'), id = document.getElementById('loginProyek').value, tetap = sel.value;
            if (REG._usersSemua) REG.users = REG._usersSemua.filter(u => u.peran !== 'SAP' && aksesProyekLokal(u, id));   // [v2.2] tanpa panggilan server
            else {
