                try { const res = await regGet('users', { proyek: id }); REG.users = res.ok ? (res.users || []).filter(u => u.peran !== 'SAP') : []; }
                catch (e) { REG.users = []; setTeks('loginError', 'Gagal memuat pengguna: ' + e.message); }
            }
            const ing = bacaSimpan(KUNCI_INGAT), pilih = (tetap && REG.users.some(u => u.nama === tetap) ? tetap : '') || (REG.sesi && REG.sesi.nama) || (ing && ing.nama) || '';
            sel.innerHTML = REG.users.length ? REG.users.map(u => `<option value="${escHtml(u.nama)}" ${pilih === u.nama ? 'selected' : ''}>${escHtml(u.nama)}${u.jabatan ? ' · ' + escHtml(u.jabatan) : ''}</option>`).join('') : '<option value="">Tidak ada pengguna untuk proyek ini</option>';
