        async function prosesLogin() {
            const nama = document.getElementById('loginNama').value, pin = document.getElementById('loginPin').value.trim();
            const proyek = document.getElementById('loginProyek').value || PROYEK.id;
            if (!nama || !pin) { setTeks('loginError', 'Pilih nama dan isi kata sandi.'); return; }
            const btn = document.getElementById('btnMasuk'); if (btn) btn.disabled = true;
            try {
                const btnIsi = btn ? btn.innerHTML : ''; if (btn) btn.innerHTML = '<i class="fas fa-spinner fa-spin me-2"></i>Memeriksa...';
                const c = REG.url ? await SIMPAN_DATA.get((REG.url) + '|' + proyek) : null;
                let res;
                try { res = await regPost({ action: 'login', nama, pin, proyek, sertakan: !!REG.url, versi: (c && c.versi) || '' }); }
                finally { if (btn) btn.innerHTML = btnIsi; }
                if (!res.ok) throw new Error(res.error);
                if (res.user.peran === 'SAP') throw new Error('Peran Tim SAP sudah dihapus. Hubungi Admin untuk penugasan ulang.');
                const ganti = proyek !== PROYEK.id;
                terapkanProyek(res.proyek || { id: proyek });
                const uu = (REG.users || []).find(x => x.nama === res.user.nama) || {};
                REG.sesi = { nama: res.user.nama, peran: res.user.peran, pin, proyek, admin: !!res.user.admin, cfg: Object.assign({}, PROYEK),
                    foto: fotoAman(res.user.foto || uu.foto), jabatan: res.user.jabatan || uu.jabatan || '', email: res.user.email || '', hp: res.user.hp || '' };
                tulisSimpan(KUNCI_SESI, REG.sesi);
                if ((document.getElementById('loginIngat') || {}).checked) tulisSimpan(KUNCI_INGAT, { nama, proyek, sandi: pin }); else { try { localStorage.removeItem(KUNCI_INGAT); } catch (e) { } }
                tutupLayarMasuk();
                notif('Selamat datang, ' + res.user.nama + ' · ' + PROYEK.id + ' ' + PROYEK.nama, 'ok');
                REG.versiServer = res.versiServer || (REG.url ? 'lama' : 'lokal');
                if (ganti) { REG.data = []; PROG.data = []; PMT.data = []; KOREKSI.data = {}; REG.dataSiap = false; REG.versiData = ''; }
                renderKoneksiReg();
                const pk = res.paket;
                if (pk && pk.ok && !REG.memuat) {   // [v2.2] data sudah ikut dalam jawaban login
                    if (pk.tidakBerubah && c) terapkanData({ ok: true, versi: c.versi, data: c.data, migrasi: pk.migrasi }, true); else terapkanData(pk);
                    REG.terakhir = new Date(); REG.error = ''; REG.dukungSemua = true;
                    renderSemuaData();
