        async function jalankanImpor(tanpaTanya) {
            if (!REG.sesi || !REG.sesi.admin) { notif('Khusus ADMIN.', 'err'); return; }
            if (MIG.jalan) return;
            if (migrasiTerkunci()) { notif('Data awal sudah disimpan & dikunci. Gunakan "Impor ulang" bila memang perlu.', 'err'); return; }
            if (!tanpaTanya && !await tanya('Impor data awal dari Excel ke server proyek ' + PROYEK.id + '?\nData yang sudah ada tidak akan digandakan.', { judul: 'Impor data awal', ok: '<i class="fas fa-cloud-arrow-up me-1"></i>Impor', bahaya: false })) return;
            MIG.jalan = true; renderBannerMigrasi();
            const log = document.getElementById('migLog'), btn = document.getElementById('btnImpor'); if (btn) btn.disabled = true;
            const tulis = t => { const l = document.getElementById('migLog'); if (l) l.innerHTML += `<div>${t}</div>`; };
            const total = { baru: 0, ada: 0, konflik: [] };
            try {
                for (const [jenis, rows] of [['progres', DATA_AWAL.progres], ['permintaan', DATA_AWAL.permintaan]]) {
                    for (let i = 0; i < rows.length; i += 25) {
                        const r = await regAksi('impor', { jenis, rows: rows.slice(i, i + 25) });
                        total.baru += r.baru; total.ada += r.ada; total.konflik.push(...(r.konflik || []));
