        const semua = PBJ.data.slice().sort((a, b) => String(b.diubahPada).localeCompare(String(a.diubahPada)));
        const rows = semua.filter(F[PBJ.filter] || F.aktif).filter(p => !q || [p.kode, p.nama, p.pemenang, p.noPR, p.noRFQ, p.noPO, p.noKontrak, ...(p.bon || []).map(b => b.nomor + ' ' + b.uraian)].join(' ').toLowerCase().includes(q));
        const akt = pbjAktif(), hps = akt.reduce((a, p) => a + N(p.hps), 0), fin = akt.filter(p => N(p.final) > 0).reduce((a, p) => a + N(p.final), 0), ef = akt.reduce((a, p) => a + N(p.efisiensi), 0);
        const alok = alokasiBon(), bonBelum = [];
        (PMT.data || []).forEach(b => { const st = statusKontrakPermintaan(b); (b.items || []).forEach((it, i) => { if (!alok.has(b.nomor + '#' + i) && !st.sudah[i]) bonBelum.push({ b, it, i }); }); });
        const chip = (v, l, n) => `<button type="button" class="reg-chip ${PBJ.filter === v ? 'aktif' : ''}" onclick="PBJ.filter='${v}'; renderPBJ()">${l}<span class="n">${n}</span></button>`;
        const entri = bolehEntri() && PBJ.dukung !== false;
        el.innerHTML = bannerServer() + `
        <div class="row g-3 mb-3">
            ${[['Paket aktif', akt.length.toLocaleString('id-ID'), akt.filter(p => p.status === 'KONTRAK').length + ' sudah jadi kontrak', '#1763B3', 'fa-gavel'],
               ['Total HPS', rpS(hps), fmtRp(hps), '#0B2B54', 'fa-scale-balanced'],
               ['Harga final pemenang', rpS(fin), akt.filter(p => p.pemenang).length + ' paket ada pemenang', '#2E9E5B', 'fa-trophy'],
               ['Efisiensi thd HPS', rpS(ef), hps ? (ef / hps * 100).toLocaleString('id-ID', { maximumFractionDigits: 1 }) + '% dari HPS' : '-', '#E3343F', 'fa-arrow-trend-down']]
            .map(k => `<div class="col-6 col-xl-3"><div class="bk-kpi" style="--w:${k[3]}"><div class="d-flex justify-content-between"><div class="l">${k[0]}</div><i class="fas ${k[4]}"></i></div><div class="v">${k[1]}</div><div class="s">${k[2]}</div></div></div>`).join('')}
        </div>
        <div class="card shadow-sm p-3 mb-3">
            <div class="d-flex flex-wrap gap-2 align-items-center mb-2">
                <div class="d-flex flex-wrap gap-1">${chip('aktif', 'Aktif', akt.length)}${chip('PROSES', 'Proses', PBJ.data.filter(F.PROSES).length)}${chip('SIAP', 'Siap kontrak', PBJ.data.filter(F.SIAP).length)}${chip('KONTRAK', 'Kontrak', PBJ.data.filter(F.KONTRAK).length)}${chip('BATAL', 'Batal', PBJ.data.filter(F.BATAL).length)}</div>
                <input type="search" class="form-control form-control-sm ms-auto" style="max-width:260px" placeholder="Cari paket, bon, vendor, PO…" value="${e(PBJ.cari)}" id="pbjCari" oninput="PBJ.cari=this.value; window.__fokus='pbjCari'; renderPBJ()">
                ${entri ? `<button type="button" class="btn btn-sm btn-primary" onclick="pbjDariBon()"><i class="fas fa-clipboard-list me-1"></i>Paket baru dari Bon</button>
                <button type="button" class="btn btn-sm btn-outline-primary" onclick="pbjBaru()"><i class="fas fa-plus me-1"></i>Paket kosong</button>
                <button type="button" class="btn btn-sm btn-light border" onclick="pbjImpor()" title="Impor berkas JSON hasil Ekspor PBJ Studio lama"><i class="fas fa-file-import me-1"></i>Impor JSON PBJ Studio</button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="histImpor()" title="Lengkapi riwayat tender yang sudah selesai (tanpa tender ulang) dan tautkan ke Bon & kontrak yang sudah ada"><i class="fas fa-clock-rotate-left me-1"></i>Impor PBJ historis</button>` : ''}
                <button type="button" class="btn btn-sm btn-light border" onclick="muatPBJ(true)" title="Muat ulang dari server"><i class="fas fa-rotate${PBJ.memuat ? ' fa-spin' : ''}"></i></button>
            </div>
            <div class="table-responsive"><table class="table table-sm table-hover align-middle mb-0 tbl-pbj">
                <thead class="table-light"><tr><th>Paket</th><th>Bon</th><th style="min-width:120px">Tahap</th><th>Pemenang</th><th class="text-end">HPS</th><th class="text-end">Final</th><th>SAP</th><th>Kontrak</th><th>Status</th><th></th></tr></thead>
                <tbody>${rows.length ? rows.map(p => { const kt = kandidatTaut(p); return `<tr>
                    <td><a href="#" class="fw-semibold" onclick="pbjBuka('${e(p.id)}'); return false;">${e(p.nama)}</a>${p.state && p.state.historis ? ' <span class="badge text-bg-dark border" title="Riwayat PBJ historis diimpor ' + e(String(p.state.historis.diimporPada || '').slice(0, 10)) + '"><i class="fas fa-clock-rotate-left me-1"></i>Historis</span>' : ''}<div class="small text-muted font-monospace">${e(p.kode)} · ${e((p.diubahPada || '').slice(0, 10))} · ${e(p.diubahOleh || '')}</div></td>
                    <td class="small">${[...new Set((p.bon || []).map(b => b.nomor))].map(n => `<span class="badge text-bg-light border font-monospace">${e(noBonPendek(n))}</span>`).join(' ') || '<span class="text-muted">—</span>'}${(p.bon || []).length ? `<div class="text-muted">${p.bon.length} item</div>` : ''}</td>
                    <td><div class="bk-prog"><div class="bar"><span style="width:${(N(p.tahap) / 12 * 100).toFixed(0)}%;background:${N(p.tahap) >= 12 ? '#2E9E5B' : '#1763B3'}"></span></div><b>${N(p.tahap)}/12</b></div></td>
                    <td class="small">${e(p.pemenang || '-')}</td>
                    <td class="text-end text-nowrap">${p.hps ? fmtRpSingkat(p.hps) : '-'}</td>
                    <td class="text-end text-nowrap">${p.final ? fmtRpSingkat(p.final) : '-'}${p.efisiensi > 0 ? `<div class="small text-success">−${fmtRpSingkat(p.efisiensi)}</div>` : ''}</td>
                    <td class="text-nowrap">${sapPills(p)}</td>
                    <td class="small">${p.noKontrak ? `<span class="font-monospace">${e(p.noKontrak.split('/').slice(0, 2).join('/'))}</span>` : kt && entri ? `<button class="btn btn-sm btn-outline-success py-0" onclick="pbjTautkan('${e(p.id)}','${e(kt.noKontrak)}')">Tautkan ${e(kt.noKontrak.split('/').slice(0, 2).join('/'))}</button>` : '<span class="text-muted">—</span>'}</td>
                    <td>${badgePBJ(p.status)}${p.status === 'BATAL' && p.alasanBatal ? `<div class="small text-muted text-truncate" style="max-width:140px" title="${e(p.alasanBatal)}">${e(p.alasanBatal)}</div>` : ''}</td>
                    <td class="text-nowrap text-end"><button class="btn btn-sm btn-light border py-0" onclick="pbjBuka('${e(p.id)}')" title="Buka"><i class="fas fa-folder-open"></i></button>
                        ${entri && p.status !== 'BATAL' && !p.noKontrak ? `<button class="btn btn-sm btn-light border py-0 text-danger" onclick="pbjBatal('${e(p.id)}')" title="Batalkan paket"><i class="fas fa-ban"></i></button>` : ''}
                        ${entri && adalahAdmin() && p.status === 'BATAL' ? `<button class="btn btn-sm btn-light border py-0" onclick="pbjPulihkan('${e(p.id)}')" title="Pulihkan (Admin)"><i class="fas fa-rotate-left"></i></button><button class="btn btn-sm btn-light border py-0 text-danger" onclick="pbjHapus('${e(p.id)}')" title="Hapus permanen (Admin)"><i class="fas fa-trash"></i></button>` : ''}</td>
                </tr>`; }).join('') : `<tr><td colspan="10" class="text-center text-muted py-4">${PBJ.memuat ? 'Memuat…' : PBJ.data.length ? 'Tidak ada paket pada filter ini.' : PBJ.dukung === false ? 'Fitur paket PBJ tersedia setelah server diperbarui ke v2.3.' : entri ? 'Belum ada paket PBJ. Mulai dari tombol <b>Paket baru dari Bon</b>.' : 'Belum ada paket PBJ.'}</td></tr>`}</tbody>
            </table></div>
        </div>
        <div class="card shadow-sm p-3">
            <div class="d-flex align-items-center mb-2"><h6 class="fw-bold mb-0"><i class="fas fa-inbox me-2"></i>Item Bon belum diproses PBJ / kontrak</h6><span class="badge text-bg-warning ms-2">${bonBelum.length}</span>
                ${entri && bonBelum.length ? '<button class="btn btn-sm btn-outline-primary ms-auto" onclick="pbjDariBon()">Proses jadi paket PBJ</button>' : ''}</div>
            ${bonBelum.length ? `<div class="table-responsive" style="max-height:280px"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>Bon</th><th>Tgl</th><th>Dept</th><th>Item</th><th class="text-end">Vol</th><th class="text-end">Estimasi</th><th>WBS</th></tr></thead><tbody>
                ${bonBelum.slice(0, 200).map(x => `<tr><td class="font-monospace small">${e(noBonPendek(x.b.nomor))}</td><td class="small">${e(x.b.tanggal || '')}</td><td class="small">${e(x.b.departemen || '')}</td><td>${x.it.kode ? `<code>${e(x.it.kode)}</code> ` : ''}${e(x.it.uraian)}</td><td class="text-end">${fmtAngka(x.it.vol)} ${e(x.it.sat || '')}</td><td class="text-end">${x.it.harga ? fmtRpSingkat(N(x.it.vol) * N(x.it.harga)) : '-'}</td><td class="small font-monospace">${e(x.it.wbs || x.b.wbs || '-')}</td></tr>`).join('')}</tbody></table></div>` : '<div class="small text-muted">Semua item Bon sudah masuk paket PBJ atau kontrak.</div>'}
        </div>`;
        kembalikanFokus();
    }

    /* =================================================================
       6. PILIH ITEM BON (modal) — Bon → PBJ tanpa duplikasi
       ================================================================= */
    window.pastikanModal = pastikanModal;   // [2.1.9] dipakai modul lain (checklist)
    function pastikanModal(id, judul, lebar) {
        let m = document.getElementById(id); if (m) return m;
        m = document.createElement('div'); m.className = 'modal fade'; m.id = id; m.tabIndex = -1;
        m.innerHTML = `<div class="modal-dialog ${lebar || 'modal-xl'} modal-dialog-scrollable modal-fullscreen-md-down"><div class="modal-content">
            <div class="modal-header" style="background:#0B2B54;color:#fff;border-bottom:3px solid #E3343F"><h5 class="modal-title" id="${id}Judul">${judul}</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Tutup"></button></div>
            <div class="modal-body" id="${id}Isi"></div><div class="modal-footer" id="${id}Kaki"></div></div></div>`;
        document.body.appendChild(m); return m;
    }
    const BP = { pilih: new Set(), cari: '', mode: 'baru', cb: null, kecuali: null, dipakaiEditor: new Set() };
    function bukaPilihBon(mode, cb) {
        BP.pilih = new Set(); BP.cari = ''; BP.mode = mode; BP.cb = cb;
        BP.kecuali = mode === 'tambah' && PBJ.ed ? PBJ.ed.id : null;
        BP.dipakaiEditor = new Set();
        if (mode === 'tambah') { try { pbjFrameApi().bonDipakai().forEach(b => BP.dipakaiEditor.add(b.nomor + '#' + b.idx)); } catch (err) { } }
        pastikanModal('modalPilihBon', '<i class="fas fa-clipboard-list me-2"></i>Pilih item Bon Permintaan');
        renderPilihBon(); tampilModal('modalPilihBon', true);
    }
    function renderPilihBon() {
        const alok = alokasiBon(BP.kecuali), q = BP.cari.trim().toLowerCase();
        const bons = (PMT.data || []).slice().sort((a, b) => String(b.tanggal).localeCompare(String(a.tanggal)))
            .filter(b => !q || [b.nomor, b.departemen, b.peminta, b.keperluan, ...(b.items || []).map(i => i.kode + ' ' + i.uraian)].join(' ').toLowerCase().includes(q));
        const isi = document.getElementById('modalPilihBonIsi');
        isi.innerHTML = `<div class="d-flex flex-wrap gap-2 mb-2 align-items-center"><input type="search" class="form-control form-control-sm" style="max-width:320px" placeholder="Cari nomor bon, item, peminta…" value="${e(BP.cari)}" oninput="BP_cari(this)">
            <span class="small text-muted ms-auto">Item yang sudah dipakai paket lain / sudah dikontrakkan tidak dapat dipilih (mencegah duplikasi).</span></div>
            ${bons.length ? bons.slice(0, 120).map(b => { const st = statusKontrakPermintaan(b); return `<div class="border rounded p-2 mb-2">
                <div class="d-flex flex-wrap gap-2 align-items-center mb-1"><span class="font-monospace fw-bold">${e(b.nomor)}</span><span class="small text-muted">${e(b.tanggal || '')} · ${e(b.departemen || '')} · ${e(b.peminta || '')}${b.keperluan ? ' · ' + e(b.keperluan) : ''}</span>
                <button type="button" class="btn btn-sm btn-link ms-auto py-0" onclick="BP_semua('${e(b.nomor)}')">pilih semua yang tersedia</button></div>
                ${(b.items || []).map((it, i) => { const k = b.nomor + '#' + i, pk = alok.get(k), ed = BP.dipakaiEditor.has(k), kon = st.sudah[i];
                    const off = !!(pk || ed || kon), ket = ed ? '<span class="badge text-bg-info">sudah di paket ini</span>' : pk ? `<span class="badge text-bg-secondary">dipakai ${e(pk.kode)}</span>` : kon ? '<span class="badge text-bg-success">sudah dikontrakkan</span>' : '';
                    return `<label class="d-flex gap-2 align-items-start py-1 border-top small ${off ? 'opacity-50' : ''}"><input type="checkbox" class="form-check-input mt-1" ${off ? 'disabled' : ''} ${BP.pilih.has(k) ? 'checked' : ''} onchange="BP_toggle('${e(k)}', this.checked)">
                        <span class="flex-grow-1">${it.kode ? `<code>${e(it.kode)}</code> ` : ''}${e(it.uraian)} · <b>${fmtAngka(it.vol)} ${e(it.sat || '')}</b>${it.harga ? ' · est. ' + fmtRp(it.harga) + '/' + e(it.sat || 'sat') : ''}${(it.wbs || b.wbs) ? ` · WBS <span class="font-monospace">${e(it.wbs || b.wbs)}</span>` : ''}</span>${ket}</label>`; }).join('')}
            </div>`; }).join('') : '<div class="text-muted small py-3 text-center">Belum ada Bon Permintaan. Buat dulu di menu Bon Permintaan.</div>'}`;
        document.getElementById('modalPilihBonKaki').innerHTML = `<span class="me-auto small"><b id="bpJumlah">${BP.pilih.size}</b> item dipilih</span>
            <button type="button" class="btn btn-light border" data-bs-dismiss="modal">Batal</button>
            <button type="button" class="btn btn-primary" onclick="BP_ok()" ${BP.pilih.size ? '' : 'disabled'} id="bpOk"><i class="fas fa-check me-1"></i>${BP.mode === 'tambah' ? 'Tambahkan ke paket' : 'Buat paket PBJ'}</button>`;
    }
    window.BP_cari = el => { BP.cari = el.value; renderPilihBon(); const i = document.querySelector('#modalPilihBonIsi input[type=search]'); if (i) { i.focus(); i.setSelectionRange(i.value.length, i.value.length); } };
    window.BP_toggle = (k, v) => { v ? BP.pilih.add(k) : BP.pilih.delete(k); const j = document.getElementById('bpJumlah'); if (j) j.textContent = BP.pilih.size; const b = document.getElementById('bpOk'); if (b) b.disabled = !BP.pilih.size; };
    window.BP_semua = nomor => {
        const b = PMT.data.find(x => x.nomor === nomor); if (!b) return; const alok = alokasiBon(BP.kecuali), st = statusKontrakPermintaan(b);
        (b.items || []).forEach((it, i) => { const k = nomor + '#' + i; if (!alok.has(k) && !BP.dipakaiEditor.has(k) && !st.sudah[i]) BP.pilih.add(k); });
        renderPilihBon();
    };
    window.BP_ok = () => {
        const list = [...BP.pilih].map(k => { const j = k.lastIndexOf('#'), nomor = k.slice(0, j), idx = Number(k.slice(j + 1)), b = PMT.data.find(x => x.nomor === nomor), it = b && b.items[idx];
            return it ? { nomor, idx, kode: it.kode || '', uraian: it.uraian || '', vol: N(it.vol), sat: it.sat || '', harga: N(it.harga), wbs: it.wbs || b.wbs || '' } : null; }).filter(Boolean);
        tampilModal('modalPilihBon', false);
        if (BP.cb) BP.cb(list);
    };

    /* =================================================================
       7. EDITOR PAKET — PBJ Studio di dalam bingkai (iframe), tersimpan ke server
       ================================================================= */
    const PBJ_HTML = "<!doctype html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n</head>\n<body>\n<title>PBJ Studio · Monitoring Pengadaan</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&family=Arimo:ital,wght@0,400;0,700;1,400&display=swap\">\n<style>\n/* Layout: header bar di atas, sidebar tahapan di kiri, area kerja form | pratinjau A4 di kanan. Dark-first, satu tema (dasbor engineering). */\n:root{\n  --bg:#0e1215; --panel:#151a1f; --panel2:#1b2228; --line:#28313a; --line2:#34404b;\n  --fg:#e4e8eb; --muted:#8b97a2; --dim:#5f6b76;\n  --accent:#f2c230; --accent-ink:#1a1503;\n  --ok:#3fbf7f; --bad:#ec5b52; --warn:#f0a03e;\n  --s1:#5aa9e6; --s2:#e58f6a; --s3:#b48ef0;\n  --f-disp:\"Barlow Condensed\",\"Arial Narrow\",sans-serif;\n  --f-body:\"IBM Plex Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --f-mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nhtml,body{height:100%}\nbody{background:var(--bg);color:var(--fg);font:14px/1.5 var(--f-body);margin:0}\nbutton,input,select,textarea{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.num,.mono{font-family:var(--f-mono);font-variant-numeric:tabular-nums}\n\n/* ---------- shell ---------- */\n.app{display:grid;grid-template-columns:248px minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);height:100%}\nheader.top{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:10px 18px;padding:10px 18px;border-bottom:1px solid var(--line);background:var(--panel);position:sticky;top:env(safe-area-inset-top,0px);z-index:5}\n.brand{display:flex;flex-direction:column;min-width:0;flex:1 1 320px}\n.brand .eyebrow{font:600 11px/1 var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}\n.brand h1{margin:3px 0 0;font:600 20px/1.15 var(--f-disp);letter-spacing:.01em;text-wrap:balance}\n.brand .sub{color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{display:flex;flex-direction:column;padding:4px 10px;border:1px solid var(--line2);border-radius:4px;background:var(--panel2);min-width:0}\n.chip b{font:500 10px/1.2 var(--f-disp);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.chip span{font:500 13px/1.3 var(--f-mono)}\n.chip.good span{color:var(--ok)}\n.actions{display:flex;gap:8px;flex-wrap:wrap}\n.btn{border:1px solid var(--line2);background:var(--panel2);padding:7px 12px;border-radius:4px;cursor:pointer;font-weight:500;font-size:13px;display:inline-flex;align-items:center;gap:6px;white-space:nowrap}\n.btn:hover{border-color:var(--muted)}\n.btn.pri{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}\n.btn.pri:hover{filter:brightness(1.08)}\n.btn.sm{padding:4px 9px;font-size:12px}\n.btn.danger{color:var(--bad)}\n.btn:disabled{opacity:.45;cursor:not-allowed}\n\nnav.side{border-right:1px solid var(--line);background:var(--panel);overflow:auto;display:flex;flex-direction:column;padding:12px 0}\n.navgrp{font:600 11px/1 var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--dim);padding:12px 18px 6px}\n.nav a{display:flex;align-items:center;gap:10px;padding:7px 18px;color:var(--fg);text-decoration:none;font-size:13px;border-left:3px solid transparent;cursor:pointer}\n.nav a:hover{background:var(--panel2)}\n.nav a.on{background:rgba(242,194,48,.10);border-left-color:var(--accent);color:var(--accent)}\n.nav .n{font:500 12px var(--f-mono);color:var(--muted);width:20px;text-align:right}\n.nav a.on .n{color:var(--accent)}\n.dot{width:8px;height:8px;border-radius:50%;flex:none;background:var(--bad)}\n.dot.ok{background:var(--ok)}\n.nav .lbl{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.side-foot{margin-top:auto;padding:14px 18px 6px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}\n.side-foot b{color:var(--fg);font-family:var(--f-mono)}\n.meter{height:6px;background:var(--line);border-radius:3px;margin-top:8px;overflow:hidden}\n.meter i{display:block;height:100%;background:var(--ok)}\n\nmain{overflow:auto;min-width:0;padding-block:18px 40px;padding-inline:20px}\n.pagehead{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:10px;margin-bottom:14px}\n.pagehead h2{margin:0;font:600 26px/1.1 var(--f-disp);text-wrap:balance}\n.pagehead .k{font:600 11px/1 var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--accent);margin-bottom:4px}\n.pagehead p{margin:4px 0 0;color:var(--muted);font-size:13px;max-width:70ch}\n\n/* ---------- panels & forms ---------- */\n.work{display:grid;grid-template-columns:minmax(0,440px) minmax(0,1fr);gap:18px;align-items:start}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:14px 16px;min-width:0}\n.panel+.panel{margin-top:14px}\n.panel h3{margin:0 0 10px;font:600 15px/1.2 var(--f-disp);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);display:flex;justify-content:space-between;align-items:center;gap:8px}\n.fg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 12px}\n.fg .full{grid-column:1/-1}\nlabel.f{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted);min-width:0}\nlabel.f input,label.f select,label.f textarea,.cell input,.cell select{background:var(--bg);border:1px solid var(--line2);border-radius:4px;padding:6px 8px;font-size:13px;color:var(--fg);width:100%;min-width:0}\nlabel.f textarea{min-height:64px;resize:vertical}\ninput[type=number]{font-family:var(--f-mono)}\n.tbl-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:4px}\ntable.t{border-collapse:collapse;width:100%;font-size:12.5px}\ntable.t th,table.t td{border-bottom:1px solid var(--line);padding:5px 7px;text-align:left;vertical-align:middle}\ntable.t th{font:600 11px/1.2 var(--f-disp);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);background:var(--panel2);white-space:nowrap}\ntable.t td.r,table.t th.r{text-align:right}\ntable.t tr:last-child td{border-bottom:0}\ntable.t .cell input,table.t .cell select{padding:4px 6px;font-size:12.5px}\ntable.t td.cell{padding:3px 4px;min-width:90px}\ntable.t td.cell.w{min-width:170px}\n.pill{display:inline-flex;align-items:center;gap:5px;padding:2px 8px;border-radius:10px;font-size:11.5px;font-weight:600;white-space:nowrap;border:1px solid}\n.pill.ok{color:var(--ok);border-color:rgba(63,191,127,.45);background:rgba(63,191,127,.08)}\n.pill.bad{color:var(--bad);border-color:rgba(236,91,82,.45);background:rgba(236,91,82,.08)}\n.pill.warn{color:var(--warn);border-color:rgba(240,160,62,.45);background:rgba(240,160,62,.08)}\n.pill.acc{color:var(--accent);border-color:rgba(242,194,48,.45);background:rgba(242,194,48,.08)}\n.note{font-size:12px;color:var(--muted);margin:8px 0 0}\n.alerts{display:flex;flex-direction:column;gap:6px;margin-top:10px}\n.alert{display:flex;gap:8px;padding:7px 10px;border-radius:4px;font-size:12.5px;border-left:3px solid var(--warn);background:rgba(240,160,62,.07)}\n.alert.bad{border-left-color:var(--bad);background:rgba(236,91,82,.07)}\n.alert.ok{border-left-color:var(--ok);background:rgba(63,191,127,.07)}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.kv{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;font-size:13px}\n.kv dt{color:var(--muted)}\n.kv dd{margin:0;font-family:var(--f-mono);text-align:right}\n.seg{display:inline-flex;border:1px solid var(--line2);border-radius:4px;overflow:hidden;flex-wrap:wrap}\n.seg button{border:0;background:transparent;padding:5px 10px;font-size:12px;cursor:pointer;border-right:1px solid var(--line2)}\n.seg button:last-child{border-right:0}\n.seg button.on{background:var(--accent);color:var(--accent-ink);font-weight:600}\n.chk{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:12.5px}\n.chk label{display:flex;gap:5px;align-items:center;cursor:pointer}\n.chk input{accent-color:var(--accent)}\n.aanrow{padding:8px 0;border-bottom:1px solid var(--line)}\n.aanrow:last-child{border-bottom:0}\n.aanrow .h{font-size:12px;color:var(--muted);margin-bottom:4px}\n\n/* ---------- preview ---------- */\n.preview{position:sticky;top:0;min-width:0}\n.pv-bar{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}\n.pv-bar .t{font:600 12px var(--f-disp);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.pv-stage{background:#252c33;border:1px solid var(--line);border-radius:6px;padding:14px;overflow:auto;max-height:calc(100vh - 170px)}\n.pv-scale{zoom:var(--z,.6)}\n.pv-scale .paper{margin:0 auto 18px;box-shadow:0 4px 18px rgba(0,0,0,.45)}\n\n/* ---------- dashboard ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin-bottom:14px}\n.kpi{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:12px 14px;min-width:0}\n.kpi .l{font:600 11px/1.2 var(--f-disp);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.kpi .v{font:500 20px/1.25 var(--f-mono);margin-top:6px;word-break:break-word}\n.kpi .s{font-size:12px;color:var(--muted);margin-top:2px}\n.kpi.ready{border-color:rgba(63,191,127,.5)}\n.kpi.ready .v{color:var(--ok);font-family:var(--f-disp);font-weight:700;letter-spacing:.06em}\n.kpi.notready{border-color:rgba(236,91,82,.5)}\n.kpi.notready .v{color:var(--bad);font-family:var(--f-disp);font-weight:700;letter-spacing:.06em}\n.grid2{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:14px}\n.grid2 + .grid2{margin-top:14px}\n.chart svg{width:100%;height:auto;display:block}\n.chart.radar svg{max-width:440px;margin:0 auto}\n.chart text{fill:var(--muted);font-family:var(--f-mono);font-size:11px}\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12px;color:var(--muted);margin-top:6px}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}\n.strip{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px;margin-top:4px}\n.strip button{border:0;border-radius:3px;padding:8px 0 6px;cursor:pointer;font:600 12px var(--f-mono);color:#0e1215;background:var(--bad)}\n.strip button.ok{background:var(--ok)}\n.strip-l{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px;font-size:10px;color:var(--muted);text-align:center;margin-top:4px;line-height:1.2}\n\n.toast{position:fixed;bottom:calc(18px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);background:var(--panel2);border:1px solid var(--line2);padding:9px 16px;border-radius:5px;font-size:13px;z-index:20;box-shadow:0 6px 24px rgba(0,0,0,.5)}\n.confirm{display:inline-flex;gap:6px;align-items:center;font-size:12px}\n\n.hint{border-color:rgba(242,194,48,.35);background:rgba(242,194,48,.05)}\n.hint h3{color:var(--accent)}\n.hint ol,.fstep ol,.plist{margin:0;padding-left:18px;font-size:12.5px;color:var(--muted)}\n.hint li,.fstep li,.plist li{margin-bottom:3px}\n.hint b,.fstep b,.plist b{color:var(--fg);font-weight:600}\n.flow{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.flow .panel+.panel{margin-top:0}\n.fstep{display:grid;grid-template-columns:30px minmax(0,1fr);gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}\n.fstep:last-child{border-bottom:0}\n.fstep>div>b{display:block;margin-bottom:3px;font-size:13.5px}\n.fnum{width:28px;height:28px;border-radius:50%;border:0;background:var(--bad);color:#0e1215;font:600 13px var(--f-mono);cursor:pointer}\n.fnum.ok{background:var(--ok)}\n@media (max-width:1180px){.work{grid-template-columns:minmax(0,1fr)}.preview{position:static}.pv-stage{max-height:none}.grid2{grid-template-columns:minmax(0,1fr)}}\n@media (max-width:860px){\n  .app{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr);height:auto;min-height:100%}\n  header.top{position:static}\n  nav.side{flex-direction:row;overflow-x:auto;border-right:0;border-bottom:1px solid var(--line);padding:6px 0}\n  .navgrp,.side-foot{display:none}\n  .nav{display:flex}\n  .nav a{border-left:0;border-bottom:3px solid transparent;padding:8px 12px;white-space:nowrap}\n  .nav a.on{border-bottom-color:var(--accent)}\n  .nav .lbl{overflow:visible}\n  main{overflow:visible;padding-inline:16px}\n  .fg{grid-template-columns:minmax(0,1fr)}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n\n/* ---------- dokumen A4 (juga dipakai untuk cetak) ---------- */\n#doccss{display:none}\n</style>\n<style id=\"docStyle\">\n.paper{width:210mm;min-height:297mm;padding:16mm 18mm 16mm 20mm;background:#fff;color:#111;font:10.5pt/1.4 Arimo,Arial,Helvetica,sans-serif;box-sizing:border-box;page:port;position:relative}\n.paper.land{width:297mm;min-height:210mm;padding:12mm 14mm;page:land;font-size:9.5pt}\n.paper *{box-sizing:border-box}\n.paper p{margin:0 0 7pt;text-align:justify}\n.paper h1{font-size:12.5pt;text-align:center;margin:8pt 0 2pt;text-decoration:underline;font-weight:700;letter-spacing:.02em}\n.paper .ctr{text-align:center}\n.paper .rt{text-align:right}\n.paper .b{font-weight:700}\n.paper .i{font-style:italic}\n.paper .u{text-decoration:underline}\n.paper .sm{font-size:8.5pt}\n.paper .xs{font-size:7.5pt}\n.paper .kop{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:2.2pt double #111;padding-bottom:5pt;margin-bottom:10pt;gap:10pt}\n.paper .kop .co{font-weight:700;font-size:13pt;letter-spacing:.02em}\n.paper .kop .ksub{font-size:8.5pt}\n.paper .kop .kr{text-align:right;font-size:8pt;line-height:1.3}\n.paper .formhead{border:1px solid #111;display:grid;grid-template-columns:1fr auto;margin-bottom:8pt}\n.paper .formhead .fl{padding:5pt 7pt;font-size:9pt}\n.paper .formhead .fr{border-left:1px solid #111;padding:5pt 9pt;font-weight:700;font-size:10pt;display:flex;align-items:center;text-align:center}\n.paper table{border-collapse:collapse;width:100%;color:#111;font-size:inherit;font-family:inherit;line-height:inherit}\n.paper td,.paper th{color:#111}\n.paper table.meta td{padding:1pt 4pt 1pt 0;vertical-align:top}\n.paper table.meta td.k{white-space:nowrap;width:1%}\n.paper table.meta td.c{width:10pt}\n.paper table.g{margin:4pt 0 8pt}\n.paper table.g th,.paper table.g td{border:1px solid #111;padding:3pt 5pt;vertical-align:top}\n.paper table.g th{background:#e9e9e9;font-weight:700;text-align:center;vertical-align:middle}\n.paper table.g td.r{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}\n.paper table.g td.c{text-align:center}\n.paper table.g tr.sec td{background:#f3f3f3;font-weight:700}\n.paper table.g tr.tot td{font-weight:700;background:#f7f7f7}\n.paper .box{display:inline-block;width:9pt;height:9pt;border:1px solid #111;margin-right:3pt;vertical-align:-1pt;text-align:center;font-size:7.5pt;line-height:8pt;font-weight:700}\n.paper .opt{display:inline-block;margin-right:9pt;white-space:nowrap}\n.paper .opt.no{color:#777;text-decoration:line-through}\n.paper .sig{display:grid;gap:10pt;margin-top:14pt;page-break-inside:avoid}\n.paper .sig .s{text-align:center;min-width:0}\n.paper .sig .sp{height:50pt}\n.paper .sig .nm{font-weight:700;text-decoration:underline}\n.paper .letter-sig{margin-top:14pt;width:62mm;page-break-inside:avoid}\n.paper .letter-sig .sp{height:52pt}\n.paper .foot{margin-top:12pt;font-size:9pt}\n.paper .stamp{position:absolute;top:8mm;right:10mm;font:700 8pt Arimo,Arial,sans-serif;color:#b00;border:1.5px solid #b00;padding:2pt 6pt;letter-spacing:.06em;transform:rotate(3deg)}\n.paper ol,.paper ul{margin:2pt 0 7pt;padding-left:16pt}\n.paper li{margin-bottom:2pt}\n.paper .hr{border-top:1px solid #111;margin:6pt 0}\n.paper .tag{font-size:8pt;border:1px solid #111;padding:1pt 5pt;display:inline-block}\n</style>\n<!--@@TEMA@@-->\n<div class=\"app\" id=\"app\">\n  <header class=\"top\">\n    <div class=\"brand\">\n      <span class=\"eyebrow\">PBJ Studio · Panel Pengadaan Barang &amp; Jasa</span>\n      <h1 id=\"hNama\">–</h1>\n      <span class=\"sub\" id=\"hProyek\">–</span>\n    </div>\n    <div class=\"chips\" id=\"hChips\"></div>\n    <div class=\"actions\">\n      <button class=\"btn pri\" id=\"btnSave\" type=\"button\">Simpan rekap</button>\n      <button class=\"btn\" id=\"btnPrint\" type=\"button\">Cetak</button>\n    </div>\n  </header>\n  <nav class=\"side\" id=\"side\" aria-label=\"Navigasi tahap\"></nav>\n  <main id=\"main\"></main>\n</div>\n<div id=\"printArea\" hidden></div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n<input type=\"file\" id=\"fileJson\" accept=\".json,application/json\" hidden>\n<input type=\"file\" id=\"fileCsv\" accept=\".csv,text/csv\" hidden>\n\n<!--@@PRA@@-->\n<script>\n\"use strict\";\n/* =========================================================\n   KONSTANTA\n   ========================================================= */\nconst BULAN=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];\nconst HARI=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];\nconst ROMAWI=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];\nconst KRIT=[\n {k:'wave',g:'A',grp:'UMUM',label:'Status Rekanan (WAVE)',b:2,ket:'RUW=100%; RTs=80%; RTd=60%; CRW=40%; Registered/WLD/WUID=0%'},\n {k:'kinerja',g:'A',grp:'UMUM',label:'Kinerja Rekanan (WAVE)',b:2,ket:'Sesuai penilaian PB-05 & PB-06 (WAVE); jika tidak ada penilaian skor 0'},\n {k:'skn',g:'A',grp:'UMUM',label:'Sisa Kemampuan Nyata/SKN (WAVE)',b:3,ket:'Sesuai data SKN pada WAVE; jika tidak ada penilaian skor 0'},\n {k:'suap',g:'A',grp:'UMUM',label:'Pengendalian Anti Penyuapan (Kebijakan & Pedoman/Prosedur)',b:2,ket:'Skor 100% bila memiliki kebijakan/sistem manajemen anti penyuapan'},\n {k:'harga',g:'B',grp:'BIAYA',label:'Harga Penawaran Final',b:25,ket:'Otomatis = MIN(1; HPS / Harga Final) dari PB-01A',auto:true},\n {k:'bayar',g:'B',grp:'BIAYA',label:'Pengakuan Progress & Cara Pembayaran',b:11,ket:'Lebih menguntungkan vs kondisi owner 100%; sama 75%; merugikan 50%'},\n {k:'um',g:'C',grp:'GARANSI/JAMINAN',label:'Uang Muka',b:5,ket:'Tanpa UM 100%; selisih >5% dari syarat WSKT 75%; >10% 50%'},\n {k:'retensi',g:'C',grp:'GARANSI/JAMINAN',label:'Retensi',b:5,ket:'Lebih lama vs syarat owner 100%; sama 75%; lebih cepat 50%; sama dengan jaminan 25%'},\n {k:'metode',g:'D',grp:'TEKNIS',label:'Metode Kerja',b:6,ket:'Approval owner 100%; sesuai rencana proyek 75%; usulan rekanan dapat diterima 50%; tidak ada 0'},\n {k:'alat',g:'D',grp:'TEKNIS',label:'Alat/Peralatan',b:6,ket:'Jumlah & kapasitas sesuai, SILO & riwayat lengkap 100%; lebih tua 75%; umur < 5 th 50%'},\n {k:'cv',g:'E',grp:'STRUKTUR ORGANISASI LAPANGAN',label:'CV & Bagan Struktur Organisasi',b:3,ket:'Personil & pengalaman sesuai syarat 100%; pengalaman kurang dapat diterima 75%; personil kurang 50%'},\n {k:'dukTender',g:'F',grp:'DUKUNGAN',label:'Memberikan Dukungan Tender',b:4,ket:'Ada surat dukungan tender 100%; tidak ada 0%'},\n {k:'dukKinerja',g:'F',grp:'DUKUNGAN',label:'Memberikan Dukungan Kinerja',b:4,ket:'Memberikan support kinerja 100%; tidak 0%'},\n {k:'mutu',g:'G',grp:'QHSE',label:'Mutu & Kualitas',b:10,ket:'Peringkat keahlian tertinggi 100%; tiap 1 level di bawahnya berkurang 25%'},\n {k:'lca',g:'G',grp:'QHSE',label:'Prosedur Life Cycle Analysis',b:2,ket:'Ada prosedur 100%; tidak ada 0'},\n {k:'schedule',g:'H',grp:'WAKTU',label:'Schedule',b:6,ket:'Lebih cepat & lengkap 100%; sama 75%; lebih lambat 2,5% lengkap 50%; tidak lengkap 25%'},\n {k:'tkdn',g:'I',grp:'TKDN',label:'Persentase TKDN',b:2,ket:'TKDN tertinggi di antara pembanding 100%; lainnya proporsional'},\n {k:'pref',g:'I',g