    function sidikEditor() { const api = pbjFrameApi(); return api ? JSON.stringify(api.ambilState()) + JSON.stringify(PBJ.ed.sap) : ''; }
    function editorBerubah() { return !!(PBJ.ed && PBJ.ed.siap && sidikEditor() !== PBJ.ed.simpanAkhir); }
