    function langkahAlur(rec, r) {
        const kon = rec && rec.noKontrak, reg = kon && (REG.data || []).find(x => x.noKontrak === kon);
        const prog = kon ? (PROG.data || []).filter(x => x.noKontrak === kon) : [];
        const bayar = prog.filter(x => x.bayar && x.bayar.status === 'DIBAYAR');
        const L = [
            ['Bon', (rec && rec.bon && rec.bon.length) || (r && r.bonN) ? 'ok' : '', ((rec && rec.bon) || []).length + ' item'],
            ['PBJ', r && r.tahap >= 12 ? 'ok' : r && r.tahap ? 'jalan' : '', (r ? r.tahap : 0) + '/12 tahap'],
            ['PR', PBJ.ed.sap.noPR ? 'ok' : '', PBJ.ed.sap.noPR || '—'], ['RFQ', PBJ.ed.sap.noRFQ ? 'ok' : '', PBJ.ed.sap.noRFQ || '—'], ['PO', PBJ.ed.sap.noPO ? 'ok' : '', PBJ.ed.sap.noPO || '—'],
            ['Kontrak', kon ? 'ok' : '', kon ? kon.split('/').slice(0, 2).join('/') + (reg ? (reg.diposting ? ' · diposting' : ' · draf') : ' · master') : '—'],
            ['Progres/BK', prog.length ? 'ok' : '', prog.length ? prog.length + ' BA · ' + rpS(prog.reduce((a, x) => a + N(x.nilai), 0)) : '—'],
            ['Bayar', prog.length && bayar.length === prog.length ? 'ok' : bayar.length ? 'jalan' : '', prog.length ? bayar.length + '/' + prog.length + ' dibayar' : '—']
        ];
        return `<div class="alur-mini">${L.map(x => `<div class="am ${x[1]}"><span class="t">${x[0]}</span><span class="v">${e(x[2])}</span></div>`).join('')}</div>`;
    }
    function renderEditorBar() {
        const bar = document.getElementById('pbjBar'); if (!bar || !PBJ.ed) return;
        const rec = PBJ.ed.rec, api = pbjFrameApi(); let r = null; try { r = api && api.ringkas(); } catch (err) { }
        const ubah = editorBerubah(), entri = bolehEntri() && PBJ.dukung !== false && !(rec && rec.status === 'BATAL');
        const bisaKontrak = entri && rec && !rec.noKontrak && r && r.siap;
        const ak = document.activeElement && document.activeElement.dataset ? document.activeElement.dataset.sap : null;
