    window.PBJ_tandaUbah = () => { const s = document.getElementById('pbjStatusSimpan'); if (s) { const u = editorBerubah(); s.className = 'small ' + (u ? 'text-danger fw-semibold' : 'text-success'); s.innerHTML = u ? '<i class="fas fa-circle me-1" style="font-size:.5rem"></i>Belum disimpan' : '<i class="fas fa-check me-1"></i>Tersimpan'; } };
    window.BP_tambah = () => window.__PBJ_HOST.tarikBon();
    async function pbjSimpan(diam) {
        if (!PBJ.ed || !cekDukung()) return false;
        const api = pbjFrameApi(); if (!api) { notif('Editor PBJ belum siap.', 'err'); return false; }
        const st = api.ambilState(), r = api.ringkas(), rec = PBJ.ed.rec;
        const bon = st.items.filter(i => i.bon).map(i => ({ nomor: i.bon.nomor, idx: i.bon.idx, kode: i.bon.kode, wbs: i.bon.wbs, uraian: i.uraian, vol: i.vol, sat: i.satuan, harga: i.hps }));
        const data = Object.assign({ nama: r.nama || (rec && rec.nama) || 'Paket PBJ', tahap: r.tahap, siap: r.siap, pemenang: r.pemenang, hps: r.hps, final: r.final, finalPpn: r.finalPpn, efisiensi: r.efisiensi, bon, state: st }, PBJ.ed.sap);
        if (rec) { data.id = rec.id; data.versi = rec.versi; }
        PBJ.ed.menyimpan = true; renderEditorBar();
        try {
            const res = await regAksi('savePBJ', { data });
            PBJ.ed.rec = res.data; PBJ.ed.id = res.data.id; simpanLokalPBJ(res.data);
            PBJ.ed.simpanAkhir = sidikEditor();
            if (!diam || !rec) notif(res.tidakBerubah ? 'Tidak ada perubahan.' : (rec ? 'Paket ' + res.data.kode + ' tersimpan · v' + res.data.versi : 'Paket ' + res.data.kode + ' dibuat · item Bon terkunci untuk paket ini'), 'ok');
            return true;
        } catch (err) { notif(err.message, 'err'); return false; }
        finally { if (PBJ.ed) { PBJ.ed.menyimpan = false; renderEditorBar(); } }
    }
    window.pbjBuka = id => { const rec = PBJ.data.find(x => x.id === id); if (!rec) return; if (PBJ.ed && editorBerubah()) { notif('Simpan atau tutup paket yang sedang dibuka dulu.', 'err'); bukaTab('pbj'); return; } bukaEditor(rec); };
