    const JENIS_SEMUA = [...JENIS_MATERIAL, ...JENIS_SERVICE];
    const KK = { st: null, r: null, rec: null };
    window.pbjBuatKontrak = async () => {
        if (!PBJ.ed || !cekDukung()) return;
