            return st.items.filter(pi => it.some(i => N(i.volume || i.volumeKontrak) === N(pi.vol) && Math.abs(N(i.hargaSatuan) - N((pi.final || {})[winId])) < 1)).length; };
        let best = null, sk = 0; (RINGKASAN || []).forEach(g => { const n = cocok(g); if (n > sk) { sk = n; best = g; } });
        return best && sk >= Math.ceil(st.items.length * 0.8) ? best.key : '';
