    /* --- verifikasi: tampilkan selisih, JANGAN ubah data --- */
    function verifikasi(st, bon, peta, kon) {
        const out = [], ok = (j, a, b, k) => out.push({ t: 'cocok', j, a, b, k }), beda = (j, a, b, k) => out.push({ t: 'beda', j, a, b, k }), kurang = (j, a, b, k) => out.push({ t: 'kurang', j, a, b, k });
        const byNama = n => (st.vendors || []).find(v => v.nama.trim().toLowerCase() === String(n || '').trim().toLowerCase());
        const win = byNama(st.pemenang), ppn = N(st.paket && st.paket.ppn), hps = hpsDari(st), cat = String(st.catatanPB10 || '');
        if (!win) { beda('Pemenang', st.pemenang || '-', 'tidak ada di database vendor', 'Periksa nama pemenang'); return out; }
        const fin = nilaiVendor(st, win.id, 'final'), finP = Math.round(fin * (1 + ppn));
        // nilai penetapan dari catatan arsip
        const mRp = cat.match(/Rp\s?([\d.]+(?:,\d+)?)\s*termasuk PPN/i);
        if (mRp) { const v = angkaID(mRp[1]); (Math.abs(v - finP) < 1 ? ok : beda)('Nilai penetapan (termasuk PPN)', 'Arsip: ' + fmtRp(v), 'Hitung PBJ: ' + fmtRp(finP), 'DPP ' + fmtRp(fin) + ' + PPN ' + Math.round(ppn * 100) + '%'); }
