        // vendor dengan harga final terendah tetapi bukan pembanding
        const pemb = (st.pemb || []).map(n => String(n).trim().toLowerCase());
        const totals = (st.vendors || []).map(v => ({ v, f: nilaiVendor(st, v.id, 'final') })).filter(x => x.f > 0).sort((a, b) => a.f - b.f);
        if (totals[0] && !pemb.includes(totals[0].v.nama.trim().toLowerCase())) beda('Harga final terendah', totals[0].v.nama + ': ' + fmtRp(totals[0].f), 'Pemenang ' + win.nama + ': ' + fmtRp(fin), 'Vendor terendah tidak termasuk 3 pembanding — pastikan alasan (gugur administrasi/teknis) terdokumentasi');
        // HPS vs Bon
        if (bon) {
            const tb = N(bon.total) || (bon.items || []).reduce((a, i) => a + N(i.vol) * N(i.harga), 0);
            (Math.abs(tb - hps) < 1 ? ok : beda)('HPS vs total Bon', 'Bon: ' + fmtRp(tb), 'HPS PBJ: ' + fmtRp(Math.round(hps)), Math.abs(tb - hps) < 1 ? '' : 'Selisih ' + fmtRp(Math.round(hps - tb)) + ' (pembulatan harga satuan)');
            st.items.forEach((pi, i) => { const bi = peta[i] >= 0 ? bon.items[peta[i]] : null;
                if (!bi) { kurang('Item ' + (i + 1) + ' tanpa pasangan Bon', pi.uraian, '—', 'Pilih baris Bon secara manual'); return; }
                if (N(bi.vol) !== N(pi.vol)) beda('Volume item ' + (i + 1), 'Bon: ' + bi.vol + ' ' + bi.sat, 'PBJ: ' + pi.vol + ' ' + pi.satuan, pi.uraian);
