        const cari = x => !q || [x.key, x.vendor, x.idVendor, x.po, x.k.pr, x.k.rfq, x.t === 'reg' ? [x.r.noPR, x.r.noRFQ, (x.r.items || []).map(i => i.uraian + ' ' + i.wbs).join(' ')].join(' ') : (x.g.cari || '')].join(' ').toLowerCase().includes(q);
        const list = semua.filter(f).filter(cari).sort((a, b) => (a.t === b.t ? 0 : a.t === 'reg' ? -1 : 1) || (a.t === 'reg' ? String(b.ubah).localeCompare(String(a.ubah)) : (urutNomor(b.key) - urutNomor(a.key)) || String(a.key).localeCompare(String(b.key))));
