    /* ---------- KPI alur pengadaan: perbaikan jumlah paket PBJ & data terbaru ---------- */
    function hitungPermintaanBelum() {
        let n = 0, nilai = 0;
        (PMT.data || []).forEach(p => {
            const st = statusKontrakPermintaan(p); if (st.kode === 'selesai') return; n++;
            (p.items || []).forEach((it, i) => { if (st.sudah && st.sudah[i]) return; const sisa = Math.max(N(it.vol) - N(((st.alok || {})[i]) || 0), 0); nilai += sisa * N(it.harga); });
        });
        return { n, nilai };
    }
    function perbaikiLangkah() {
        const el = document.getElementById('alurPengadaan'); if (!el || !REG.sesi) return;
        const cari = l => [...el.querySelectorAll('.alur-step')].find(s => { const x = s.querySelector('.l'); return x && x.textContent.trim() === l; });
        const set = (s, v, sub) => { if (!s) return; const a = s.querySelector('.v'), b = s.querySelector('.s'); if (a && a.textContent !== v) a.textContent = v; if (b && sub !== undefined && b.textContent !== sub) b.textContent = sub; };
        // Langkah: Permintaan (alokasi multi-kontrak & tautan PBJ ikut dihitung)
        const pb = hitungPermintaanBelum();
        set(cari('Permintaan Barang'), (PMT.data || []).length.toLocaleString('id-ID'), pb.n + ' belum dikontrakkan · ' + rpS(pb.nilai));
        setTeks('heroPermintaan', pb.n.toLocaleString('id-ID'));
        // Langkah: Paket PBJ — seluruh paket aktif (proses, siap, sampai kontrak), bukan hanya yang masih proses
