        if (s2) {
            if (PBJ.dukung === false) set(s2, '0', 'perlu server v2.3+');
            else { const akt = (PBJ.data || []).filter(p => p.status !== 'BATAL'), c = st => akt.filter(p => p.status === st).length;
                set(s2, akt.length.toLocaleString('id-ID'), (c('PROSES') + c('DRAF')) + ' proses · ' + c('SIAP') + ' siap · ' + c('KONTRAK') + ' kontrak · HPS ' + rpS(akt.reduce((a, p) => a + N(p.hps), 0))); }
        }
