    /* =================================================================
       5. MULTI-WBS / MULTI-KONTRAK — satu Bon Permintaan dibagi ke beberapa WBS & kontrak
          per item: Σ volume alokasi ≤ volume Bon (dicek server). Nilai = volume × harga Bon,
          jadi total tidak pernah digandakan. Alokasi tersimpan terpisah di <ID>_AlokasiBon.
       ================================================================= */
    function alokItem(nomor, idx) { return alokAktif().filter(a => a.bonNomor === nomor && Number(a.bonIdx) === Number(idx)); }
    function volAlok(nomor, idx) { return alokItem(nomor, idx).reduce((a, x) => a + N(x.volume), 0); }
    // status Bon: item yang seluruh volumenya sudah dialokasikan ke kontrak dihitung "sudah dikontrakkan"
    (function () {
        const asli = window.statusKontrakPermintaan; if (typeof asli !== 'function') return;
        window.statusKontrakPermintaan = function (p) {
            const r = asli.apply(this, arguments);
            try {
                const A = alokAktif().filter(a => a.bonNomor === p.nomor); if (!A.length) return r;
                const sudah = (r.sudah || []).slice(), alok = {};
                (p.items || []).forEach((it, i) => { const v = A.filter(a => Number(a.bonIdx) === i).reduce((s, a) => s + N(a.volume), 0); if (v > 0) alok[i] = v; if (v > 0 && v >= N(it.vol) - 1e-9) sudah[i] = true; });
                const n = sudah.filter(Boolean).length, total = (p.items || []).length, kontrak = [...new Set([...(r.kontrak || []), ...A.map(a => a.noKontrak)])];
                const sebagian = n > 0 || Object.keys(alok).length > 0;
                return Object.assign({}, r, { kode: n >= total ? 'selesai' : sebagian ? 'sebagian' : 'belum', n, total, kontrak, sudah, alok, wbsAlokasi: [...new Set(A.map(a => a.wbs))] });
            } catch (err) { return r; }
        };
    })();
    function daftarKontrakPilihan() {
        const m = new Map();
        ((typeof RINGKASAN !== 'undefined' && RINGKASAN) || []).forEach(g => { if (kontrakValid(g.key)) m.set(g.key, { no: g.key, vendor: g.namaVendor || '', sumber: g.baru ? 'Register' : 'Master' }); });
        (REG.data || []).forEach(r => { if (r.noKontrak) m.set(r.noKontrak, { no: r.noKontrak, vendor: r.namaVendor || '', sumber: r.diposting ? 'Register' : 'Draf Register' }); });
        (PBJ.data || []).forEach(p => { if (p.status !== 'BATAL' && p.noKontrak && !m.has(p.noKontrak)) m.set(p.noKontrak, { no: p.noKontrak, vendor: p.pemenang || '', sumber: 'PBJ' }); });
        return [...m.values()].sort((a, b) => urutNomor(b.no) - urutNomor(a.no) || a.no.localeCompare(b.no));
    }
    function daftarWbs() {
        const s = new Set();
        ((typeof RINGKASAN !== 'undefined' && RINGKASAN) || []).forEach(g => (g.items || []).forEach(i => { const w = String(i.wbs || '').trim(); if (w) s.add(w); }));
        (PMT.data || []).forEach(p => { if (p.wbs) s.add(String(p.wbs).trim()); (p.items || []).forEach(i => { if (i.wbs) s.add(String(i.wbs).trim()); }); });
        MP.alok.forEach(a => { if (a.wbs) s.add(a.wbs); });
        return [...s].sort();
    }
    const AL = { nomor: '', form: null };
    window.AL214 = AL;
    window.bukaAlokasi214 = nomor => {
