  }
  function cariDokArsip(vkey, jenis, noKontrak) {
    const kand = arsipAktif().filter(d => d.kodeVendor === vkey && d.jenis === jenis && (!d.noKontrak || d.noKontrak === noKontrak || pendek(d.noKontrak) === pendek(noKontrak)));
    kand.sort((a, b) => ((b.noKontrak ? 1 : 0) - (a.noKontrak ? 1 : 0)) || String(b.dibuatPada).localeCompare(String(a.dibuatPada)));
    return kand;
  }
  async function isiDariArsip() {
