      const d = cocok.find(x => statusDok(x).k !== 'lewat'), basi = cocok.find(x => statusDok(x).k === 'lewat');
      if (!d) { if (basi) kadaluwarsa.push({ k, d: basi }); return; }
      tersedia.push({ k, d });
    }));
    const bisa = peng() && !r.verified;
    tersedia.forEach(({ k, d }) => {
      const lama = r.items[k] || {};
      if ((lama.status === 'ADA' && lama.file && lama.file.idServer) || lama.status === 'NA') return;
      if (diisi.some(z => z.k === k)) return;
      if (!bisa) { diisi.push({ k, d, saran: true }); return; }
      r.items[k] = Object.assign({}, lama, { status: 'ADA', file: d.file, tgl: d.tglTerbit || lama.tgl || '', alasan: '',
        ket: ('Arsip Vendor' + (d.noDok ? ' · No. ' + d.noDok : '') + (d.berlakuSd ? ' · berlaku s.d. ' + tglID(d.berlakuSd) : '')).slice(0, 350) });
      diisi.push({ k, d });
    });
