  /* ======================= C. NOTIFIKASI TERPADU ======================= */
  async function muatRingkas(paksa) {
    if (!sesi() || !REG.url || !(S.fitur || []).includes('checklistTagihan')) return;
    const F = window.MP219_KEU;
    if (F && F.siap && F.ringkas) { S.ringkas = F.ringkas; S.ringkasPada = Date.now(); }
    if (S.ringkasMuat || (!paksa && S.ringkas && Date.now() - S.ringkasPada < 10 * 60000)) return;
    S.ringkasMuat = true;
    try { const r = await regAksi('checklistRingkas'); const o = {}; (r.data || []).forEach(x => { o[x.id] = x; }); S.ringkas = o; S.ringkasPada = Date.now(); }
    catch (err) { console.warn('[2.2.0] ringkas checklist', err.message); }
    finally { S.ringkasMuat = false; hitungNotif(); }
  }
  const TOTAL_TPL = { ALAT: 25, BAHAN: 25, SUBKON: 26 };
  const katDari = no => { const m = String(no || '').toUpperCase().match(/(?:^|\/)(SPSA|SPM|SPPM|SPKP|SPPP|SPK)(?=\/|$)/); return m ? { SPSA: 'ALAT', SPM: 'BAHAN', SPPM: 'BAHAN', SPKP: 'SUBKON', SPPP: 'SUBKON', SPK: 'SUBKON' }[m[1]] : ''; };
  function hitungNotif() {
    const L = [];
    if (!sesi()) { S.notif = L; gambarLonceng(); return; }
    // 1) kontrak H-30 (termasuk yang sudah lewat & belum selesai)
    semuaK().forEach(x => {
      const m = masa(x); if (!['lewat', 'h30'].includes(m.k)) return;
      L.push({ g: 'kontrak', urg: m.sisa < 0 ? 0 : m.sisa <= 7 ? 1 : 2, sisa: m.sisa, judul: pendek(x.key) + ' · ' + (x.vendor || '-'), ket: (m.sisa < 0 ? 'Masa berlaku berakhir ' : 'Berakhir ') + tglID(m.tgl), nilai: m.label,
        buka: x.t === 'reg' ? `bukaEditReg(${E(JSON.stringify(x.r.id))})` : `bukaKoreksi(${E(JSON.stringify(x.g.key))})` });
    });
    // 2) dokumen vendor H-7 (termasuk kedaluwarsa yang masih aktif di arsip)
    arsipAktif().forEach(d => {
      const st = statusDok(d); if (!['lewat', 'h7'].includes(st.k)) return;
      L.push({ g: 'dokumen', urg: st.sisa < 0 ? 0 : 1, sisa: st.sisa, judul: (NAMA_JENIS[d.jenis] || d.jenis) + ' · ' + d.namaVendor, ket: 'Berlaku s.d. ' + tglID(d.berlakuSd) + (d.noKontrak ? ' · ' + pendek(d.noKontrak) : ''), nilai: st.label,
        buka: `mp220ArsipBuka(${E(JSON.stringify(d.kodeVendor))})` });
    });
    // 3) tagihan dengan kelengkapan dokumen < 100 % (belum dibayar)
    if (S.ringkas) (PROG.data || []).forEach(e => {
      if (e.bayar && e.bayar.status === 'DIBAYAR') return;
      const r = S.ringkas[e.id], kat = (r && r.kategori) || katDari(e.noKontrak); if (!kat) return;
      const tot = (r && N(r.total)) || TOTAL_TPL[kat] || 0, lk = r ? N(r.lengkap) : 0; if (!tot || lk >= tot) return;
      let vendor = '-'; try { vendor = barisBK(e).vendor || '-'; } catch (err) { }
