  }
  function turunan() {
    const nama = (typeof PROYEK !== 'undefined' && PROYEK.kso) || 'WASKITA - NINDYA KSO';
    const kso = /\bKSO\b|\bJ\.?O\b|JOINT/i.test(nama);
    return { bentuk: kso ? 'KSO' : 'TUNGGAL', nama, singkatan: (nama.replace(/^PT\.?\s+/i, '').trim().charAt(0) || 'W').toUpperCase(), anggota: [], unit: '', asal: 'proyek' };
  }
