  const bawaan = n => String(n || '').replace(/\s+/g, ' ').trim().toUpperCase().replace(/\s*[-–—]\s*/g, '-') === 'WASKITA-NINDYA KSO';
  function gantiTeks(s) { const idt = identitas(); if (bawaan(idt.nama)) return s; return String(s).replace(RE_DEF, m => m === m.toUpperCase() ? idt.nama.toUpperCase() : judul(idt.nama)); }
