        const nm = judul(idt.nama);
        const eb = document.querySelector('.masuk-eyebrow'); if (eb) eb.textContent = nm + ' · Pengadaan Terintegrasi';
        const kk = document.querySelector('.masuk-kaki'); if (kk && kk.firstChild && kk.firstChild.nodeType === 3) kk.firstChild.textContent = '© ' + nm + ' · Monitoring Pengadaan ';
        if (bawaan(idt.nama) && !ID.namaTerap) return;
        const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, { acceptNode: n => {
          const p = n.parentNode; if (!p || /^(SCRIPT|STYLE|TEXTAREA|INPUT)$/.test(p.nodeName) || p.closest('#mp224Lapis,[contenteditable="true"]')) return NodeFilter.FILTER_REJECT;
          return /nindya|NINDYA/i.test(n.nodeValue) || (ID.namaTerap && n.nodeValue.indexOf(ID.namaTerap) >= 0) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP; } });
        const L = []; while (w.nextNode()) L.push(w.currentNode);
        L.forEach(n => { let v = n.nodeValue; v = v.replace(RE_DEF, m => m === m.toUpperCase() ? idt.nama.toUpperCase() : nm);
          if (ID.namaTerap && ID.namaTerap !== idt.nama) { v = v.split(ID.namaTerap.toUpperCase()).join(idt.nama.toUpperCase()).split(judul(ID.namaTerap)).join(nm); }
          if (v !== n.nodeValue) n.nodeValue = v; });
