    const db = d.db, dbHtml = !db ? '' : db.galat ? `<div class="mp2619-al no">Lokasi database tidak terbaca: ${E(db.galat)}</div>` : `<div class="mp2619-db"><p class="mp2619-h">Lokasi database (data aplikasi disimpan di sini)</p><p><a href="${E(db.url)}" target="_blank" rel="noopener"><b>${E(db.nama)}</b> · buka spreadsheet</a> <span class="mp2619-m">${db.terikat ? 'Sheet tempat Apps Script terpasang' : 'file mandiri, dibuat otomatis oleh server'}</span></p>${db.terakhir ? `<p class="mp2619-m">Simpan terakhir: ${E(tgl(db.terakhir.pada))} · ${E(db.terakhir.oleh)} · ${E(db.terakhir.aksi)}</p>` : ''}<table class="mp2619-tb"><thead><tr><th>Sheet proyek ${E(db.proyek)}</th><th>Baris data</th></tr></thead><tbody>${(db.sheet || []).slice(0, 12).map(s => `<tr><td>${E(s.nama)}</td><td>${E(s.baris)}</td></tr>`).join('')}</tbody></table><p class="mp2619-m">Kolom terakhir (DATA) berisi catatan lengkap; kolom lain ringkasan agar mudah dibaca. Jangan mengubah isi sheet langsung.</p></div>`;   // [2.6.21]
